INSERT INTO _fields_wd1_plan (site_id, column_name, old_value, new_value, change_key, reason, evidence) VALUES
    ('4d9953ff-ccc7-4818-8677-5cb5ce9f4cab'::uuid, 'geom', 'SRID=4326;POINT(44.03333 40.08194)', '0101000020E6100000DE195199C7044640B2E86C19D4134440', 'fields-wd1-2026-09-26b-s004-rollback:4d9953ff-ccc7-4818-8677-5cb5ce9f4cab:geom', 'rollback of fields-wd1-2026-09-26b-s004: geom ''0101000020E6100000DE195199C7044640B2E86C19D4134440'' restored on Ancient City of Armavir', '[{"source": "https://en.wikipedia.org/wiki/Armavir_(ancient_city)", "url": "https://en.wikipedia.org/wiki/Armavir_(ancient_city)", "quote": "40°04′55″N 44°02′00″E", "outcome": "found"}, {"source": "https://imperium.ahlfeldt.se/places/21804", "url": "https://imperium.ahlfeldt.se/places/21804", "quote": "40.08065, 44.03403", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0005)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia places the ruins of ancient Armavir on the hill 1 km west of Armavir village at 40°04′55″N 44°02′00″E, and the Digital Atlas of the Roman Empire places Armaouira 0.2 km from it; the stored point (40.155, 44.037) is the modern town of Armavir, 8 km north.", "value_page": null}]'::jsonb),
    ('4d9953ff-ccc7-4818-8677-5cb5ce9f4cab'::uuid, 'lat', '40.08194', '40.15491025750943', 'fields-wd1-2026-09-26b-s004-rollback:4d9953ff-ccc7-4818-8677-5cb5ce9f4cab:lat', 'rollback of fields-wd1-2026-09-26b-s004: lat ''40.15491025750943'' restored on Ancient City of Armavir', '[{"source": "https://en.wikipedia.org/wiki/Armavir_(ancient_city)", "url": "https://en.wikipedia.org/wiki/Armavir_(ancient_city)", "quote": "40°04′55″N 44°02′00″E", "outcome": "found"}, {"source": "https://imperium.ahlfeldt.se/places/21804", "url": "https://imperium.ahlfeldt.se/places/21804", "quote": "40.08065, 44.03403", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0005)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia places the ruins of ancient Armavir on the hill 1 km west of Armavir village at 40°04′55″N 44°02′00″E, and the Digital Atlas of the Roman Empire places Armaouira 0.2 km from it; the stored point (40.155, 44.037) is the modern town of Armavir, 8 km north.", "value_page": null}]'::jsonb),
    ('4d9953ff-ccc7-4818-8677-5cb5ce9f4cab'::uuid, 'lon', '44.03333', '44.03734127483379', 'fields-wd1-2026-09-26b-s004-rollback:4d9953ff-ccc7-4818-8677-5cb5ce9f4cab:lon', 'rollback of fields-wd1-2026-09-26b-s004: lon ''44.03734127483379'' restored on Ancient City of Armavir', '[{"source": "https://en.wikipedia.org/wiki/Armavir_(ancient_city)", "url": "https://en.wikipedia.org/wiki/Armavir_(ancient_city)", "quote": "40°04′55″N 44°02′00″E", "outcome": "found"}, {"source": "https://imperium.ahlfeldt.se/places/21804", "url": "https://imperium.ahlfeldt.se/places/21804", "quote": "40.08065, 44.03403", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0005)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia places the ruins of ancient Armavir on the hill 1 km west of Armavir village at 40°04′55″N 44°02′00″E, and the Digital Atlas of the Roman Empire places Armaouira 0.2 km from it; the stored point (40.155, 44.037) is the modern town of Armavir, 8 km north.", "value_page": null}]'::jsonb),
    ('4d9953ff-ccc7-4818-8677-5cb5ce9f4cab'::uuid, 'period_name', '1500 - 500 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s004-rollback:4d9953ff-ccc7-4818-8677-5cb5ce9f4cab:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''3000 - 1500 BC'' restored on Ancient City of Armavir', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-800) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('4d9953ff-ccc7-4818-8677-5cb5ce9f4cab'::uuid, 'period_start', '-800', '-3000', 'fields-wd1-2026-09-26b-s004-rollback:4d9953ff-ccc7-4818-8677-5cb5ce9f4cab:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-3000'' restored on Ancient City of Armavir', '[{"source": "https://en.wikipedia.org/wiki/Armavir_(ancient_city)", "url": "https://en.wikipedia.org/wiki/Armavir_(ancient_city)", "quote": "During the first half of the 8th century BC, King Argishti I of Urartu built a fortress in the area and named it Argishtikhinili.", "outcome": "found"}, {"source": "https://www.urartianmonuments.com/armavir/", "url": "https://www.urartianmonuments.com/armavir/", "quote": "The Urartian settlement itself was founded by King Argišti I around 776–760 BCE.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0002)", "decision": "replace", "status": "MISSING", "reasoning": "The city on the hills at Armavir (Argishtikhinili) was founded by Argishti I of Urartu in the 8th century BC (c. 776-760 BCE per the foundation inscriptions); the earlier habitation is only stated for the wider area or region, undated by year, so the securely attested start is the 8th-century-BC foundation, in the 1500 - 500 BC bucket, not 3000 - 1500 BC.", "value_page": null}]'::jsonb),
    ('4d9953ff-ccc7-4818-8677-5cb5ce9f4cab'::uuid, 'site_type', 'City', 'Megalithic stones', 'fields-wd1-2026-09-26b-s004-rollback:4d9953ff-ccc7-4818-8677-5cb5ce9f4cab:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Megalithic stones'' restored on Ancient City of Armavir', '[{"source": "https://en.wikipedia.org/wiki/Armavir_(ancient_city)", "url": "https://en.wikipedia.org/wiki/Armavir_(ancient_city)", "quote": "was a large commercial city and the capital of ancient Armenia during the reign of the Orontid dynasty", "outcome": "found"}, {"source": "https://www.urartianmonuments.com/armavir/", "url": "https://www.urartianmonuments.com/armavir/", "quote": "The city of Argištiḫinili consisted of two citadels built on separate hills and a lower town surrounding them.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0002)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources describe Armavir (Argishtikhinili), near the modern village of Armavir in Armenia, as a city with citadels and a lower town, not as a megalithic site; the type is City.", "value_page": null}]'::jsonb),
    ('4df0cef0-d57b-417b-a0e3-c949b0811685'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s004-rollback:4df0cef0-d57b-417b-a0e3-c949b0811685:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''1500 - 500 BC'' restored on Cape St. Athanasius Ancient Settlement', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('4df0cef0-d57b-417b-a0e3-c949b0811685'::uuid, 'period_start', NULL, '-1500', 'fields-wd1-2026-09-26b-s004-rollback:4df0cef0-d57b-417b-a0e3-c949b0811685:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-1500'' restored on Cape St. Athanasius Ancient Settlement', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0013)", "decision": "clear", "status": "MISSING", "reasoning": "Archaeology in Bulgaria and English Wikipedia say the earliest finds are Chalcolithic and Bronze Age but give no year, and the Bulgarian Wikipedia dates the stray axes and arrowheads either to the late Chalcolithic or the Early Bronze Age. The Thracian cult site of the 6th-5th century BC is a later phase, not the start. No two independent sources date the start, so the stored -1500 is unsupported.", "value_page": null}]'::jsonb),
    ('4df0cef0-d57b-417b-a0e3-c949b0811685'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Cape_St._Athanasius', 'https://en.wikipedia.org/wiki/Cape_St._Athanasius_ancient_settlement', 'fields-wd1-2026-09-26b-s004-rollback:4df0cef0-d57b-417b-a0e3-c949b0811685:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/Cape_St._Athanasius_ancient_settlement'' restored on Cape St. Athanasius Ancient Settlement', '[{"source": "https://en.wikipedia.org/wiki/Cape_St._Athanasius", "url": "https://en.wikipedia.org/wiki/Cape_St._Athanasius", "quote": "Baptistry, Cape St. Athanasius", "outcome": "found"}, {"source": "https://archaeologyinbulgaria.com/background-infonotes/fortresses-cities/st-athanasius-cape-fortress-byala-varna-district-bulgaria/", "url": "https://archaeologyinbulgaria.com/background-infonotes/fortresses-cities/st-athanasius-cape-fortress-byala-varna-district-bulgaria/", "quote": "St. Athanasius Cape Fortress – Byala, Varna District, Bulgaria", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0013)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL ''Cape_St._Athanasius_ancient_settlement'' is a redirect to the article ''Cape St. Athanasius'', whose infobox and whole content cover the archaeological site (its finds, fortress and baptistry), so the canonical article URL replaces the redirect. Archaeology in Bulgaria covers the same site as the St. Athanasius Cape Fortress at Byala.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Cape St. Athanasius", "unreadable": false, "wikibase_item": "Q55606585"}}]'::jsonb),
    ('4df5f7bf-8b73-4602-9d6e-dab158203820'::uuid, 'site_type', 'City', 'City/town/settlement', 'fields-wd1-2026-09-26b-s004-rollback:4df5f7bf-8b73-4602-9d6e-dab158203820:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''City/town/settlement'' restored on Chocolá', '[{"source": "https://floridapress.org/9780813052205/water-cacao-and-the-early-maya-of-chocola/", "url": "https://floridapress.org/9780813052205/water-cacao-and-the-early-maya-of-chocola/", "quote": "Water, Cacao, and the Early Maya of Chocolá explores the often-overlooked Southern Maya Region of Guatemala, closely examining the near-legendary ancient city of Chocolá.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Chocol%C3%A1", "url": "https://en.wikipedia.org/wiki/Chocol%C3%A1", "quote": "Archaeoastronomical research has tentatively identified crucial alignments from structures in the administrative center of the city that reflect primordial measurements that underlay development of the Maya calendar.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0074)", "decision": "replace", "status": "MISSING", "reasoning": "The University Press of Florida (the excavators'' monograph) and Wikipedia both describe Chocolá as an ancient city with elite, administrative and commoner sectors, so the specific type City fits.", "value_page": null}]'::jsonb),
    ('4e0540cd-333a-4808-8c4e-fa136957c934'::uuid, 'source_url', 'https://es.wikipedia.org/wiki/Templo_de_H%C3%A9rcules_(Am%C3%A1n)', 'https://en.wikipedia.org/wiki/Temple_of_Hercules_(Amman)', 'fields-wd1-2026-09-26b-s004-rollback:4e0540cd-333a-4808-8c4e-fa136957c934:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/Temple_of_Hercules_(Amman)'' restored on Roman Temple of Hercules', '[{"source": "https://es.wikipedia.org/wiki/Templo_de_H%C3%A9rcules_(Am%C3%A1n)", "url": "https://es.wikipedia.org/wiki/Templo_de_H%C3%A9rcules_(Am%C3%A1n)", "quote": "también conocido como Gran templo de Amán", "outcome": "found"}, {"source": "https://es.wikipedia.org/wiki/Templo_de_H%C3%A9rcules_(Am%C3%A1n)", "url": "https://es.wikipedia.org/wiki/Templo_de_H%C3%A9rcules_(Am%C3%A1n)", "quote": "En el templo de Hércules, la restauración se centró en el pórtico, el sector noroeste del podio y tres de sus columnas.", "outcome": "found"}, {"source": "https://acorjordan.org/research/publications/acor-publications/great-temple-architecture/", "url": "https://acorjordan.org/research/publications/acor-publications/great-temple-architecture/", "quote": "is popularly known as the Temple of Hercules and can be dated to the term of the Roman governor Geminius Marcianus", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0091)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English URL is only a redirect into the Great Temple section of the Amman Citadel article, which is about the whole hill; the Spanish Wikipedia has an article of its own on the Temple of Hercules (Great Temple of Amman), and ACOR''s page on the Great Temple of Amman confirms the site under that name.", "value_page": {"lang": "es", "problem": null, "resolved_title": "Templo de Hércules (Amán)", "unreadable": false, "wikibase_item": "Q20423672"}}]'::jsonb),
    ('4e2c28ed-7ff1-4e9c-9e59-e33b24783af4'::uuid, 'period_name', NULL, '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s004-rollback:4e2c28ed-7ff1-4e9c-9e59-e33b24783af4:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''4500 - 3000 BC'' restored on El Oso, Ávila', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('4e2c28ed-7ff1-4e9c-9e59-e33b24783af4'::uuid, 'period_start', NULL, '-4000', 'fields-wd1-2026-09-26b-s004-rollback:4e2c28ed-7ff1-4e9c-9e59-e33b24783af4:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-4000'' restored on El Oso, Ávila', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0131)", "decision": "clear", "status": "MISSING", "reasoning": "The stored 4000 BC is far too early for a Vettonian verraco; the sources about this sculpture only call it of Vettonian chronology and the verracos.es catalogue leaves its century blank, so no two independent sources date this very statue.", "value_page": null}]'::jsonb),
    ('4e2c28ed-7ff1-4e9c-9e59-e33b24783af4'::uuid, 'source_url', 'http://www.verracos.es/verraco/130', 'https://en.wikipedia.org/wiki/El_Oso,_%C3%81vila', 'fields-wd1-2026-09-26b-s004-rollback:4e2c28ed-7ff1-4e9c-9e59-e33b24783af4:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/El_Oso,_%C3%81vila'' restored on El Oso, Ávila', '[{"source": "http://www.verracos.es/verraco/130", "url": "http://www.verracos.es/verraco/130", "quote": "Foto verraco de El Oso. Se conserva en la plaza del pueblo, frente a la iglesia.", "outcome": "found"}, {"source": "https://www.guiarepsol.com/es/fichas/localidad/el-oso-2613/", "url": "https://www.guiarepsol.com/es/fichas/localidad/el-oso-2613/", "quote": "un verraco vetón, muy típico de Ávila, y pariente de los Toros de Guisando, que la gente del pueblo creyó un oso en lugar de un toro. Hoy esa venerable talla está emplazada frente a la iglesia de San Pedro Apóstol", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0131)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is about the municipality; the verraco has no Wikipedia article of its own, and the verracos.es catalogue entry 130 is the dedicated record of this sculpture (description, measurements, location in front of the church, bibliography).", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('4e399e7e-d5e9-49f8-a1de-6e404a740a55'::uuid, 'geom', 'SRID=4326;POINT(-6.064722 38.949167)', '0101000020E61000004B3A5483525518C0835ABF5BD06C4340', 'fields-wd1-2026-09-26b-s004-rollback:4e399e7e-d5e9-49f8-a1de-6e404a740a55:geom', 'rollback of fields-wd1-2026-09-26b-s004: geom ''0101000020E61000004B3A5483525518C0835ABF5BD06C4340'' restored on Turuñuelo', '[{"source": "https://es.wikipedia.org/wiki/El_Turu%C3%B1uelo", "url": "https://es.wikipedia.org/wiki/El_Turu%C3%B1uelo", "quote": "38.949167, -6.064722", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/9440868452", "url": "https://www.openstreetmap.org/node/9440868452", "quote": "38.9493350, -6.0649199", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0135)", "decision": "replace", "status": "CONFLICT", "reasoning": "Spanish Wikipedia places El Turuñuelo at 38.949167, -6.064722 and the OpenStreetMap archaeological-site node ''Casas del Turuñuelo'' at 38.9493350, -6.0649199 (the BIC decree''s UTM polygon centres on the same spot on the right bank of the Guadiana); the stored point lies about 11 km south, near Guareña town, so it is replaced.", "value_page": null}]'::jsonb),
    ('4e399e7e-d5e9-49f8-a1de-6e404a740a55'::uuid, 'lat', '38.949167', '38.850108593401295', 'fields-wd1-2026-09-26b-s004-rollback:4e399e7e-d5e9-49f8-a1de-6e404a740a55:lat', 'rollback of fields-wd1-2026-09-26b-s004: lat ''38.850108593401295'' restored on Turuñuelo', '[{"source": "https://es.wikipedia.org/wiki/El_Turu%C3%B1uelo", "url": "https://es.wikipedia.org/wiki/El_Turu%C3%B1uelo", "quote": "38.949167, -6.064722", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/9440868452", "url": "https://www.openstreetmap.org/node/9440868452", "quote": "38.9493350, -6.0649199", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0135)", "decision": "replace", "status": "CONFLICT", "reasoning": "Spanish Wikipedia places El Turuñuelo at 38.949167, -6.064722 and the OpenStreetMap archaeological-site node ''Casas del Turuñuelo'' at 38.9493350, -6.0649199 (the BIC decree''s UTM polygon centres on the same spot on the right bank of the Guadiana); the stored point lies about 11 km south, near Guareña town, so it is replaced.", "value_page": null}]'::jsonb),
    ('4e399e7e-d5e9-49f8-a1de-6e404a740a55'::uuid, 'lon', '-6.064722', '-6.0833225746305954', 'fields-wd1-2026-09-26b-s004-rollback:4e399e7e-d5e9-49f8-a1de-6e404a740a55:lon', 'rollback of fields-wd1-2026-09-26b-s004: lon ''-6.0833225746305954'' restored on Turuñuelo', '[{"source": "https://es.wikipedia.org/wiki/El_Turu%C3%B1uelo", "url": "https://es.wikipedia.org/wiki/El_Turu%C3%B1uelo", "quote": "38.949167, -6.064722", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/9440868452", "url": "https://www.openstreetmap.org/node/9440868452", "quote": "38.9493350, -6.0649199", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0135)", "decision": "replace", "status": "CONFLICT", "reasoning": "Spanish Wikipedia places El Turuñuelo at 38.949167, -6.064722 and the OpenStreetMap archaeological-site node ''Casas del Turuñuelo'' at 38.9493350, -6.0649199 (the BIC decree''s UTM polygon centres on the same spot on the right bank of the Guadiana); the stored point lies about 11 km south, near Guareña town, so it is replaced.", "value_page": null}]'::jsonb),
    ('4e399e7e-d5e9-49f8-a1de-6e404a740a55'::uuid, 'site_type', 'Sanctuary', 'Temple complex', 'fields-wd1-2026-09-26b-s004-rollback:4e399e7e-d5e9-49f8-a1de-6e404a740a55:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Temple complex'' restored on Turuñuelo', '[{"source": "https://greekcitytimes.com/2026/09/28/unique-bronze-votive-cart-tartessian-site-spain", "url": "https://greekcitytimes.com/2026/09/28/unique-bronze-votive-cart-tartessian-site-spain", "quote": "The sanctuary itself was deliberately sealed and buried during the late 5th century BC, preserving an extraordinary archaeological record of Tartessian religious practices, feasting and long-distance cultural exchange.", "outcome": "found"}, {"source": "https://www.revistadearte.com/2017/07/03/hallados-restos-de-16-caballos-sacrificados-en-el-santuario-tartesico-del-turunuelo-badajoz/", "url": "https://www.revistadearte.com/2017/07/03/hallados-restos-de-16-caballos-sacrificados-en-el-santuario-tartesico-del-turunuelo-badajoz/", "quote": "El santuario tartésico del Turuñuelo de Guareña, en Badajoz, del siglo V a.C., una joya arqueológica por sus novedosas técnicas arquitectónicas y por su estado de conservación", "outcome": "found"}, {"source": "https://es.wikipedia.org/wiki/El_Turu%C3%B1uelo", "url": "https://es.wikipedia.org/wiki/El_Turu%C3%B1uelo", "quote": "el inmediato incendio del santuario tartésico, que fue enterrado y abandonado.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0135)", "decision": "replace", "status": "MISSING", "reasoning": "Greek City Times (on the Casas del Turuñuelo votive cart), the excavators'' CSIC release and Spanish Wikipedia all describe Turuñuelo as a Tartessian sanctuary - one monumental ritual building with an oxhide altar and a sacrificial courtyard - not a complex of temples, so Sanctuary is the most specific type the sources support.", "value_page": null}]'::jsonb),
    ('4f32070e-25b0-4f96-a895-37499099f745'::uuid, 'period_name', '3000 - 1500 BC', '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s004-rollback:4f32070e-25b0-4f96-a895-37499099f745:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''4500 - 3000 BC'' restored on Catholme Ceremonial Complex', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-2500) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('4f32070e-25b0-4f96-a895-37499099f745'::uuid, 'period_start', '-2500', '-4500', 'fields-wd1-2026-09-26b-s004-rollback:4f32070e-25b0-4f96-a895-37499099f745:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-4500'' restored on Catholme Ceremonial Complex', '[{"source": "https://en.wikipedia.org/wiki/Catholme_ceremonial_complex", "url": "https://en.wikipedia.org/wiki/Catholme_ceremonial_complex", "quote": "about 2500 BC it was made into a segmented enclosure, and the timber circle, displaying upright oak posts, was built about this time", "outcome": "found"}, {"source": "https://www.digitaldigging.net/catholme-neolithic-complex-timber-circles/", "url": "https://www.digitaldigging.net/catholme-neolithic-complex-timber-circles/", "quote": "with construction dating to 2570–2470BC – the time of the recutting of the ring ditch at the Sunburst Monument", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=14862", "url": "https://www.megalithic.co.uk/article.php?sid=14862", "quote": "Post pits date from 2880-2410BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0031)", "decision": "replace", "status": "MISSING", "reasoning": "The excavator''s account (Digital Digging, Henry Chapman) dates the oak-post timber circle to 2570–2470 BC and the Sunburst ditch recut to about the same time; Wikipedia gives about 2500 BC and the Megalithic Portal, from Where Rivers Meet, 2880–2410 BC. The earlier Sunburst pits are undated, so the securely attested start is c. 2500 BC, in the 3000 - 1500 BC bucket, not 4500 - 3000 BC.", "value_page": null}]'::jsonb),
    ('4f366f34-983c-42e1-a89d-7e8f5f77cdce'::uuid, 'site_type', 'City/town/settlement', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s004-rollback:4f366f34-983c-42e1-a89d-7e8f5f77cdce:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Fortress/citadel'' restored on Machu Picchu', '[{"source": "https://www.megalithic.co.uk/article.php?sid=15998", "url": "https://www.megalithic.co.uk/article.php?sid=15998", "quote": "Type: Ancient Village or Settlement", "outcome": "found"}, {"source": "https://consultasenlinea.mincetur.gob.pe/fichaInventario/index.aspx?cod_Ficha=917", "url": "https://consultasenlinea.mincetur.gob.pe/fichaInventario/index.aspx?cod_Ficha=917", "quote": "Machu Picchu es el sitio arqueológico inca más sobresaliente debido a su creativo diseño urbano, la belleza de su arquitectura y el fino trabajo en piedra de sus construcciones. En su planificación se aprovechó notablemente la topografía de la cima de la montaña a la que transformó en una imponente llaqta.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0111)", "decision": "replace", "status": "CONFLICT", "reasoning": "Machu Picchu was not a fortress: the Megalithic Portal types it as an ancient settlement (a royal Inca estate with living quarters for up to 1000 people) and Peru''s MINCETUR inventory describes its urban design and calls it an imposing llaqta (Inca town); ''citadel'' is only the popular label, so the Wikidata class ancient city''s settlement type fits.", "value_page": null}]'::jsonb),
    ('4fb5bdfa-4ff6-4897-a54c-7533e2bd2308'::uuid, 'period_name', '500 BC - 1 AD', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s004-rollback:4fb5bdfa-4ff6-4897-a54c-7533e2bd2308:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''1500 - 500 BC'' restored on Calleva Atrebatum', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-25) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('4fb5bdfa-4ff6-4897-a54c-7533e2bd2308'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Calleva_Atrebatum', 'https://en.wikipedia.org/wiki/Archaeology', 'fields-wd1-2026-09-26b-s004-rollback:4fb5bdfa-4ff6-4897-a54c-7533e2bd2308:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/Archaeology'' restored on Calleva Atrebatum', '[{"source": "https://en.wikipedia.org/wiki/Calleva_Atrebatum", "url": "https://en.wikipedia.org/wiki/Calleva_Atrebatum", "quote": "Calleva Atrebatum (\"Calleva of the Atrebates\") was an Iron Age oppidum, the capital of the Atrebates tribe.", "outcome": "found"}, {"source": "https://www.english-heritage.org.uk/visit/places/silchester-roman-city-walls-and-amphitheatre/history/", "url": "https://www.english-heritage.org.uk/visit/places/silchester-roman-city-walls-and-amphitheatre/history/", "quote": "After the Roman conquest in AD 43 it developed into the town of Calleva Atrebatum.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0030)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the generic article ''Archaeology''; the site''s own English Wikipedia article is Calleva Atrebatum, and English Heritage names the same town at Silchester.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Calleva Atrebatum", "unreadable": false, "wikibase_item": "Q1027253"}}]'::jsonb),
    ('4fe33206-24d7-4d57-9bde-670139eed9cb'::uuid, 'site_type', 'Barrow', 'Necropolis/tombs complex', 'fields-wd1-2026-09-26b-s004-rollback:4fe33206-24d7-4d57-9bde-670139eed9cb:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Necropolis/tombs complex'' restored on Hastings Hill', '[{"source": "https://sitelines.newcastle.gov.uk/SMR/113", "url": "https://sitelines.newcastle.gov.uk/SMR/113", "quote": "A small round barrow, on the highest point of Hasting Hill, at its west end.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=4678", "url": "https://www.megalithic.co.uk/article.php?sid=4678", "quote": "Type: Round Barrow(s)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0035)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Tyne and Wear HER and the Megalithic Portal both record the site as a single round barrow (with about ten burials inside), so ''Barrow'' is more specific and accurate than ''Necropolis/tombs complex''.", "value_page": null}]'::jsonb),
    ('4fe33206-24d7-4d57-9bde-670139eed9cb'::uuid, 'source_url', 'https://sitelines.newcastle.gov.uk/SMR/113', 'https://en.wikipedia.org/wiki/Hastings_Hill', 'fields-wd1-2026-09-26b-s004-rollback:4fe33206-24d7-4d57-9bde-670139eed9cb:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/Hastings_Hill'' restored on Hastings Hill', '[{"source": "https://sitelines.newcastle.gov.uk/SMR/113", "url": "https://sitelines.newcastle.gov.uk/SMR/113", "quote": "Site Name Hasting Hill Barrow", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=4678", "url": "https://www.megalithic.co.uk/article.php?sid=4678", "quote": "Hastings Hill, the tumulus is at the very top.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0035)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the 1960s housing estate of Hastings Hill; the barrow has no Wikipedia article, and the Tyne and Wear Historic Environment Record entry ''Hasting Hill Barrow'' is the heritage-register page about this very site; the Megalithic Portal page on the same barrow names it Hastings Hill, the spelling the estate later took (the Sunderland Echo explains the added ''s'').", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('5003c338-1646-4bd1-8c28-67827b3d8ff6'::uuid, 'period_name', '1500 - 500 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s004-rollback:5003c338-1646-4bd1-8c28-67827b3d8ff6:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''500 BC - 1 AD'' restored on Labranda Ruins', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-700) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5003c338-1646-4bd1-8c28-67827b3d8ff6'::uuid, 'period_start', '-700', '-500', 'fields-wd1-2026-09-26b-s004-rollback:5003c338-1646-4bd1-8c28-67827b3d8ff6:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-500'' restored on Labranda Ruins', '[{"source": "https://srii.org/pages/labaunda-excavations", "url": "https://srii.org/pages/labaunda-excavations", "quote": "The earliest evidence for the cult of Zeus at Labraunda at the site dates to the middle of the 7th century BC.", "outcome": "found"}, {"source": "https://perseus-aa.github.io/items/aa_3934.html", "url": "https://perseus-aa.github.io/items/aa_3934.html", "quote": "The original site of the 7th century B.C. may have been simply a sacred grove of plane trees.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0145)", "decision": "replace", "status": "MISSING", "reasoning": "The Swedish Research Institute in Istanbul, which runs the excavations, dates the earliest evidence of the Zeus cult at Labraunda to the middle of the 7th century BC, and the Perseus Art and Archaeology entry places the original sanctuary in the 7th century B.C.; the start therefore lies in 1500 - 500 BC, not at 500 BC. (Earlier Early Bronze Age stray finds are reported without a date that could be quoted.)", "value_page": null}]'::jsonb),
    ('5003c338-1646-4bd1-8c28-67827b3d8ff6'::uuid, 'site_type', 'Sanctuary', 'Megalithic stones', 'fields-wd1-2026-09-26b-s004-rollback:5003c338-1646-4bd1-8c28-67827b3d8ff6:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Megalithic stones'' restored on Labranda Ruins', '[{"source": "https://perseus-aa.github.io/items/aa_3934.html", "url": "https://perseus-aa.github.io/items/aa_3934.html", "quote": "A major religious sanctuary and refuge in the Carian territory of Mylasa.", "outcome": "found"}, {"source": "https://srii.org/pages/labaunda-excavations", "url": "https://srii.org/pages/labaunda-excavations", "quote": "became famous in the 4th century BC for sheltering the Sanctuary of Zeus Labraundos.", "outcome": "found"}, {"source": "https://topostext.org/place/374278SLab", "url": "https://topostext.org/place/374278SLab", "quote": "Labraunda, Classical to Late Antique Zeus sanctuary in Caria (Aegean Turkey)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0145)", "decision": "replace", "status": "CONFLICT", "reasoning": "Perseus, the excavators'' institute (SRII) and ToposText all describe Labraunda as the sanctuary of Zeus Labraundos, not a settlement and not a megalithic monument, so the type is Sanctuary.", "value_page": null}]'::jsonb),
    ('5025eee3-28ea-46d6-b2c3-dbb1f38a24d6'::uuid, 'site_type', 'City', 'Temple complex', 'fields-wd1-2026-09-26b-s004-rollback:5025eee3-28ea-46d6-b2c3-dbb1f38a24d6:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Temple complex'' restored on Pinara', '[{"source": "https://en.wikipedia.org/wiki/Pinara", "url": "https://en.wikipedia.org/wiki/Pinara", "quote": "was a large city of ancient Lycia at the foot of Mount Cragus", "outcome": "found"}, {"source": "https://www.lycianmonuments.com/pinara/", "url": "https://www.lycianmonuments.com/pinara/", "quote": "The city of Pinara is located on the eastern slopes of the southern Antikragos Mountains (Baba Dağı), east of the Gulf of Fethiye, overlooking the Xanthos Valley.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0147)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and Lycian Monuments both describe Pinara as a Lycian city with temples, theatre, agora and tombs among its remains; it is a city, not a temple complex.", "value_page": null}]'::jsonb),
    ('504bf30a-c4a0-48e7-8bbc-378b585b59b5'::uuid, 'period_name', '500 BC - 1 AD', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s004-rollback:504bf30a-c4a0-48e7-8bbc-378b585b59b5:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''3000 - 1500 BC'' restored on Carteia', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-400) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('504bf30a-c4a0-48e7-8bbc-378b585b59b5'::uuid, 'period_start', '-400', '-3000', 'fields-wd1-2026-09-26b-s004-rollback:504bf30a-c4a0-48e7-8bbc-378b585b59b5:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-3000'' restored on Carteia', '[{"source": "https://titulihispaniaeparsoccidentalis.letras.ulisboa.pt/?page_id=3912", "url": "https://titulihispaniaeparsoccidentalis.letras.ulisboa.pt/?page_id=3912", "quote": "A mediados del siglo IV a.C. la población desde Cerro del Prado se desplazó a un nuevo asentamiento más próximo a la costa que sería el verdadero origen de Carteia, a la que llegarían incluso colonos procedentes de Cartago.", "outcome": "found"}, {"source": "https://www.europasur.es/campo-de-gibraltar/carteia-historia-politica-enclave-portuario_0_2005691734.html", "url": "https://www.europasur.es/campo-de-gibraltar/carteia-historia-politica-enclave-portuario_0_2005691734.html", "quote": "los vestigios más antiguos hallados en el Cortijo del Rocadillo, de época púnica, no pueden llevarse más allá de mediados del siglo IV a.C.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0129)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Tituli Hispaniae corpus (Universidade de Lisboa) and Europa Sur, citing the Universidad Autónoma de Madrid excavations, date the true origin of Carteia at El Rocadillo to the mid-4th century BC, when the Phoenician Cerro del Prado settlement 2 km away moved to the coast; the stored 3000 BC and Wikipedia''s legendary 940 BC are not the site''s attested start, so the value is -400 in the 500 BC - 1 AD bucket.", "value_page": null}]'::jsonb),
    ('5077f16f-1d87-4be3-a870-35f3e1cf55fe'::uuid, 'period_name', '4500 - 3000 BC', '< 4500 BC', 'fields-wd1-2026-09-26b-s004-rollback:5077f16f-1d87-4be3-a870-35f3e1cf55fe:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''< 4500 BC'' restored on Nobbin', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3500) = ''4500 - 3000 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5077f16f-1d87-4be3-a870-35f3e1cf55fe'::uuid, 'period_start', '-3500', '-5000', 'fields-wd1-2026-09-26b-s004-rollback:5077f16f-1d87-4be3-a870-35f3e1cf55fe:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-5000'' restored on Nobbin', '[{"source": "https://de.wikipedia.org/wiki/Gro%C3%9Fsteingrab_Nobbin", "url": "https://de.wikipedia.org/wiki/Gro%C3%9Fsteingrab_Nobbin", "quote": "3500 bis 2800 v. Chr.", "outcome": "found"}, {"source": "https://www.auf-nach-mv.de/reiseziele/a-grosssteingrab-nobbin", "url": "https://www.auf-nach-mv.de/reiseziele/a-grosssteingrab-nobbin", "quote": "Megalithgrab aus der Trichterbecherkultur (ca. 4100-2800 v. Chr.)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0059)", "decision": "replace", "status": "MISSING", "reasoning": "German Wikipedia dates the grave''s construction to 3500-2800 BC and the regional tourism portal assigns it to the Funnelbeaker culture of c. 4100-2800 BC; both put the start in the 4500-3000 BC bucket, not before 4500 BC as stored.", "value_page": null}]'::jsonb),
    ('5077f16f-1d87-4be3-a870-35f3e1cf55fe'::uuid, 'source_url', 'https://de.wikipedia.org/wiki/Gro%C3%9Fsteingrab_Nobbin', 'https://en.wikipedia.org/wiki/Nobbin', 'fields-wd1-2026-09-26b-s004-rollback:5077f16f-1d87-4be3-a870-35f3e1cf55fe:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/Nobbin'' restored on Nobbin', '[{"source": "https://de.wikipedia.org/wiki/Gro%C3%9Fsteingrab_Nobbin", "url": "https://de.wikipedia.org/wiki/Gro%C3%9Fsteingrab_Nobbin", "quote": "Das Großsteingrab Nobbin (auch Großsteingrab Riesenberg genannt) ist eine megalithische Grabanlage der jungsteinzeitlichen Trichterbecherkultur bei Nobbin", "outcome": "found"}, {"source": "http://grosssteingraeber.de/seiten/deutschland/mecklenburg-vorpommern/insel-ruegen/nobbin.php", "url": "http://grosssteingraeber.de/seiten/deutschland/mecklenburg-vorpommern/insel-ruegen/nobbin.php", "quote": "Das Großsteingrab Nobbin bei Arkona", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0059)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about the Ortsteil; the grave has no English article, but its own German Wikipedia article covers exactly this monument, as the independent grosssteingraeber.de page confirms.", "value_page": {"lang": "de", "problem": null, "resolved_title": "Großsteingrab Nobbin", "unreadable": false, "wikibase_item": "Q18624785"}}]'::jsonb),
