    ('50e2e3a4-4f3e-4b1e-bd7a-8b97404f59c8'::uuid, 'site_type', 'Settlement', 'City/town/settlement', 'fields-wd1-2026-09-26b-s004-rollback:50e2e3a4-4f3e-4b1e-bd7a-8b97404f59c8:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''City/town/settlement'' restored on Nipisat Island', '[{"source": "http://www.sisimiut.museum.gl/The_Saqqaq_culture_%E2%80%93_the_first_inhabitants_of_West_Greenland", "url": "http://www.sisimiut.museum.gl/The_Saqqaq_culture_%E2%80%93_the_first_inhabitants_of_West_Greenland", "quote": "The exhibition centres on the archaeological discoveries made in the excavation of the Saqqaq summer settlement on the island Nipisat, south of Sisimiut.", "outcome": "found"}, {"source": "https://tidsskrift.dk/meddrgroenland_man_soc/article/view/147038", "url": "https://tidsskrift.dk/meddrgroenland_man_soc/article/view/147038", "quote": "For more than a millennium, the site was visited briefly from time to time, at least during spring, summer and early autumn.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0074)", "decision": "replace", "status": "CONFLICT", "reasoning": "Nipisat is a Saqqaq seasonal dwelling site; the Sisimiut Museum calls it the Saqqaq summer settlement on the island and the excavation report describes a site visited seasonally for more than a millennium, so Settlement fits, not a city or town.", "value_page": null}]'::jsonb),
    ('50e2e3a4-4f3e-4b1e-bd7a-8b97404f59c8'::uuid, 'source_url', 'https://tidsskrift.dk/meddrgroenland_man_soc/article/view/147038', 'https://en.wikipedia.org/wiki/Nipisat_Island', 'fields-wd1-2026-09-26b-s004-rollback:50e2e3a4-4f3e-4b1e-bd7a-8b97404f59c8:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/Nipisat_Island'' restored on Nipisat Island', '[{"source": "https://tidsskrift.dk/meddrgroenland_man_soc/article/view/147038", "url": "https://tidsskrift.dk/meddrgroenland_man_soc/article/view/147038", "quote": "From 1989 to 1994, more than 200 m2 were excavated at the Saqqaq site of Nipisat, situated on a small island 15 km south of Sisimiut.", "outcome": "found"}, {"source": "http://www.sisimiut.museum.gl/The_Saqqaq_culture_%E2%80%93_the_first_inhabitants_of_West_Greenland", "url": "http://www.sisimiut.museum.gl/The_Saqqaq_culture_%E2%80%93_the_first_inhabitants_of_West_Greenland", "quote": "The exhibition centres on the archaeological discoveries made in the excavation of the Saqqaq summer settlement on the island Nipisat, south of Sisimiut.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0074)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the island as a whole; the Saqqaq site has no article of its own, and the open-access excavation monograph ''Nipisat - a Saqqaq Culture Site in Sisimiut'' (Meddelelser om Grønland) is a page about this very site.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('50f3f5c5-fcc1-443e-b516-9aaf6ca13d0c'::uuid, 'period_name', NULL, '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s004-rollback:50f3f5c5-fcc1-443e-b516-9aaf6ca13d0c:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''4500 - 3000 BC'' restored on Ballyalton Court Cairn', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('50f3f5c5-fcc1-443e-b516-9aaf6ca13d0c'::uuid, 'period_start', NULL, '-4000', 'fields-wd1-2026-09-26b-s004-rollback:50f3f5c5-fcc1-443e-b516-9aaf6ca13d0c:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-4000'' restored on Ballyalton Court Cairn', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0101)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia, the Megalithic Portal and the German article describe the Neolithic court tomb and its 1933 excavation but print no year; the only dated page found is a genetic-ancestry site listing aDNA samples, so no two independent sources date the start.", "value_page": null}]'::jsonb),
    ('51023eb3-d454-4077-a1c0-2fadb0cf79f6'::uuid, 'period_name', '1500 - 500 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s004-rollback:51023eb3-d454-4077-a1c0-2fadb0cf79f6:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''500 BC - 1 AD'' restored on Ptolemais (Cyrenaica)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-700) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('51023eb3-d454-4077-a1c0-2fadb0cf79f6'::uuid, 'period_start', '-700', '-500', 'fields-wd1-2026-09-26b-s004-rollback:51023eb3-d454-4077-a1c0-2fadb0cf79f6:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-500'' restored on Ptolemais (Cyrenaica)', '[{"source": "https://en.wikipedia.org/wiki/Ptolemais,_Cyrenaica", "url": "https://en.wikipedia.org/wiki/Ptolemais,_Cyrenaica", "quote": "What had been a small Greek settlement of unknown name that originated in the late 7th century BC and that acted as a port for the city of Barca", "outcome": "found"}, {"source": "https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.04.0006%3Aentry%3Dptolemais-2", "url": "https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.04.0006%3Aentry%3Dptolemais-2", "quote": "A Greek settlement, name unknown, was established here in the late 7th c. B.C. and became the port of Barke, the rich colony of Kyrene 25 km inland on the plateau. Ptolemy III (246-221 B.C.) refounded it as Ptolemais.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0093)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia and the Princeton Encyclopedia of Classical Sites both date the first settlement at Ptolemais (Tolmeita), the port of Barca, to the late 7th century BC, before Ptolemy III''s refoundation in 246-221 BC; the start is the 7th century BC, in the 1500 - 500 BC bucket, not the stored 500 BC - 1 AD.", "value_page": null}]'::jsonb),
    ('51aa1b30-451a-4cab-a0fb-50710f87e13a'::uuid, 'period_name', '< 4500 BC', '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s004-rollback:51aa1b30-451a-4cab-a0fb-50710f87e13a:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''4500 - 3000 BC'' restored on Uçan ağıl', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-4850) = ''< 4500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('51aa1b30-451a-4cab-a0fb-50710f87e13a'::uuid, 'period_start', '-4850', '-4500', 'fields-wd1-2026-09-26b-s004-rollback:51aa1b30-451a-4cab-a0fb-50710f87e13a:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-4500'' restored on Uçan ağıl', '[{"source": "https://journals.openedition.org/paleorient/1675", "url": "https://journals.openedition.org/paleorient/1675", "quote": "The Early Chalcolithic levels of Uçan Ağıl have been radiocarbon-dated to the 4850-4600 BCE time span", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/U%C3%A7an_a%C4%9F%C4%B1l", "url": "https://en.wikipedia.org/wiki/U%C3%A7an_a%C4%9F%C4%B1l", "quote": "It is dated at ca 4850-4350 BC time span, but was also occupied in the 3rd millennium BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0009)", "decision": "replace", "status": "MISSING", "reasoning": "The excavator (Marro 2022) radiocarbon-dates the earliest, Early Chalcolithic occupation of the camp site to ca. 4850 BCE, and Wikipedia gives the same ca 4850-4350 BC span; the start therefore lies before 4500 BC, outside the stored bucket.", "value_page": null}]'::jsonb),
    ('51aa1b30-451a-4cab-a0fb-50710f87e13a'::uuid, 'site_type', 'Settlement', 'City/town/settlement', 'fields-wd1-2026-09-26b-s004-rollback:51aa1b30-451a-4cab-a0fb-50710f87e13a:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''City/town/settlement'' restored on Uçan ağıl', '[{"source": "https://journals.openedition.org/paleorient/1675", "url": "https://journals.openedition.org/paleorient/1675", "quote": "This paper will thus focus on Uçan Ağıl and Nakhchivan Tepe, two settlements located in Nakhchivan", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/U%C3%A7an_a%C4%9F%C4%B1l", "url": "https://en.wikipedia.org/wiki/U%C3%A7an_a%C4%9F%C4%B1l", "quote": "This settlement is important in terms of spreading and learning the Dalma culture in Azerbaijan and South Caucasus", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0009)", "decision": "replace", "status": "MISSING", "reasoning": "Both sources call Uçan Ağıl a settlement (a seasonal pastoral camp site), never a city or town, so the specific type Settlement replaces the compound City/town/settlement.", "value_page": null}]'::jsonb),
    ('51e6e482-0301-4200-9719-17e8b548a8db'::uuid, 'site_type', 'City', 'Temple complex', 'fields-wd1-2026-09-26b-s004-rollback:51e6e482-0301-4200-9719-17e8b548a8db:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Temple complex'' restored on Historic Site Tipasa', '[{"source": "https://en.wikipedia.org/wiki/Tipasa", "url": "https://en.wikipedia.org/wiki/Tipasa", "quote": "The Roman city was built on three small hills which overlooked the sea, nearly 20 km. east from Caesarea (capital of Mauretania Caesariensis).", "outcome": "found"}, {"source": "https://www.livius.org/articles/place/tipasa/", "url": "https://www.livius.org/articles/place/tipasa/", "quote": "Tipasa: Phoenician colony, Numidian city, Roman port and city.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0003)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and Livius both describe Tipasa as an ancient city (Punic trading post, then Roman colonia with forum, theatre, amphitheatre, churches and houses inside a city wall); it is a whole city, not a temple complex.", "value_page": null}]'::jsonb),
    ('521164cc-282e-46aa-8204-9c06a9627697'::uuid, 'source_url', 'https://www.livius.org/articles/place/nihata-niha/', 'https://en.wikipedia.org/wiki/Niha,_Zahl%C3%A9', 'fields-wd1-2026-09-26b-s004-rollback:521164cc-282e-46aa-8204-9c06a9627697:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/Niha,_Zahl%C3%A9'' restored on Niha, Zahlé', '[{"source": "https://www.livius.org/articles/place/nihata-niha/", "url": "https://www.livius.org/articles/place/nihata-niha/", "quote": "Nihata: site in the Bekaa valley with three Roman temples, modern Niha.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=18018", "url": "https://www.megalithic.co.uk/article.php?sid=18018", "quote": "Site Name: Nihata Temple of Hadaranes Alternative Name: Niha Temple of Hadaranes Country: Lebanon", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0092)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about the village of Niha; no Wikipedia article exists for its temples, and Livius''s Nihata (Niha) page is about the ancient temple site itself, which the Megalithic Portal records independently.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
