    ('52827c54-91cb-4902-99fb-7b0860a71e36'::uuid, 'period_start', NULL, '-3000', 'fields-wd1-2026-09-26b-s004-rollback:52827c54-91cb-4902-99fb-7b0860a71e36:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-3000'' restored on Tlalpan', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0098)", "decision": "clear", "status": "MISSING", "reasoning": "The Spanish Wikipedia article on the historic town says nothing is known of the date of its foundation (\"No se sabe nada sobre la fecha exacta de su fundación\"), and INAH only dates the Nahua occupation of the wider territory to the 7th century AD and Cuicuilco (a separate site) earlier; no two sources date the start of Tlalpan itself, least of all to 3000-1500 BC, so the field is emptied.", "value_page": null}]'::jsonb),
    ('52827c54-91cb-4902-99fb-7b0860a71e36'::uuid, 'source_url', 'https://es.wikipedia.org/wiki/Centro_hist%C3%B3rico_de_Tlalpan', 'https://en.wikipedia.org/wiki/History', 'fields-wd1-2026-09-26b-s004-rollback:52827c54-91cb-4902-99fb-7b0860a71e36:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/History'' restored on Tlalpan', '[{"source": "https://es.wikipedia.org/wiki/Centro_hist%C3%B3rico_de_Tlalpan", "url": "https://es.wikipedia.org/wiki/Centro_hist%C3%B3rico_de_Tlalpan", "quote": "Villa de Tlalpan, San Agustín de las Cuevas, Ciudad de Tlalpan o, como es más conocida hoy, Tlalpan es uno de los 12 pueblos de la alcaldía Tlalpan de las poblaciones más antiguas del Distrito Federal, incluso anterior a la Ciudad de México.", "outcome": "found"}, {"source": "https://lugares.inah.gob.mx/en/node/4792", "url": "https://lugares.inah.gob.mx/en/node/4792", "quote": "Tlalpan was declared a Zone of Historical Monuments on 5 December 1986.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0098)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the generic Wikipedia article ''History''; the site is the old town of Tlalpan (the historic centre, Villa de Tlalpan / San Agustin de las Cuevas), whose own article is the Spanish Wikipedia ''Centro historico de Tlalpan'', while the English ''Tlalpan'' article covers the whole borough; INAH''s register entry for the Tlalpan Historical Monuments Zone confirms the place.", "value_page": {"lang": "es", "problem": null, "resolved_title": "Centro histórico de Tlalpan", "unreadable": false, "wikibase_item": "Q5762141"}}]'::jsonb),
