    ('532b3d3d-df65-40bd-8a8f-6f1112da97de'::uuid, 'source_url', 'https://coflein.gov.uk/en/sites/92058', 'https://en.wikipedia.org/wiki/Pen-y-crug', 'fields-wd1-2026-09-26b-s004-rollback:532b3d3d-df65-40bd-8a8f-6f1112da97de:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/Pen-y-crug'' restored on Pen-y-crug', '[{"source": "https://coflein.gov.uk/en/sites/92058", "url": "https://coflein.gov.uk/en/sites/92058", "quote": "Pen-y-crug is a large, oval, multivallate hillfort which encloses the summit of a prominent, isolated hill about 2km north-west of the confluence of the rivers Usk and Honddu at Brecon.", "outcome": "found"}, {"source": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=1726", "url": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=1726", "quote": "Pen-y-Crug hillfort is situated about 1 mile west of Slwch Camp, on an isolated outcrop to the north-west of Brecon.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0155)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is about the hill (geology, access) with one sentence on the hillfort; the RCAHMW Coflein record NPRN 92058 (Pen-y-Crug hillfort) is about the hillfort itself, and Cadw''s record BR063 names the same monument independently.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
