    ('54874f2a-164e-4956-b5d8-de8834348ce1'::uuid, 'period_start', '-3500', '-3000', 'fields-wd1-2026-09-26b-s004-rollback:54874f2a-164e-4956-b5d8-de8834348ce1:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-3000'' restored on Apesokari', '[{"source": "https://www.aegeussociety.org/en/useful_websites/apesokari-tholos-tomb-b-study-project/", "url": "https://www.aegeussociety.org/en/useful_websites/apesokari-tholos-tomb-b-study-project/", "quote": "One of them is Tholos Tomb B. It is a stone built monument, used in the Early and Middle Minoan Period (c. 3500-1650 BC).", "outcome": "found"}, {"source": "https://pleiades.stoa.org/places/435488939/json", "url": "https://pleiades.stoa.org/places/435488939/json", "quote": "Minoan tomb in the Mesara Plain in south-central Crete constructed during the Early Minoan I period (ca. 3100-2650 BCE)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0061)", "decision": "replace", "status": "MISSING", "reasoning": "The cemetery''s oldest monument, Tholos Tomb B, was in use from c. 3500 BC (Aegeus Society, on the Apesokari Tholos B study project) and built in Early Minoan I, ca. 3100-2650 BCE (Pleiades); both put the start before 3000 BC, in the 4500-3000 BC bucket, not the stored 3000-1500 BC one.", "value_page": null}]'::jsonb),
