    ('54bbb6a0-65d3-42c2-a995-0469957a1313'::uuid, 'site_type', 'Settlement', 'City/town/settlement', 'fields-wd1-2026-09-26b-s004-rollback:54bbb6a0-65d3-42c2-a995-0469957a1313:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''City/town/settlement'' restored on Zyndram''s Hill', '[{"source": "https://en.wikipedia.org/wiki/Zyndram%27s_Hill", "url": "https://en.wikipedia.org/wiki/Zyndram%27s_Hill", "quote": "It was a prehistoric defensive settlement occupied in the Early Bronze Age (1750-1550 BC", "outcome": "found"}, {"source": "https://ruj.uj.edu.pl/handle/item/130709/pbn", "url": "https://ruj.uj.edu.pl/handle/item/130709/pbn", "quote": "Considering the results of fieldwork and other applied methods we can assume, that the enclosed settlement in Maszkowice functioned as an isolated point located in scarcely populated area.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0117)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is not a town but a prehistoric fortified (enclosed, defensive) hilltop settlement, so the narrower canonical type Settlement fits better than City/town/settlement.", "value_page": null}]'::jsonb),
