    ('5583b792-3239-4362-a627-1923a30356dc'::uuid, 'period_name', '3000 - 1500 BC', '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s004-rollback:5583b792-3239-4362-a627-1923a30356dc:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''4500 - 3000 BC'' restored on Alvastra Pile-Dwelling', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3000) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5583b792-3239-4362-a627-1923a30356dc'::uuid, 'period_start', '-3000', '-4500', 'fields-wd1-2026-09-26b-s004-rollback:5583b792-3239-4362-a627-1923a30356dc:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-4500'' restored on Alvastra Pile-Dwelling', '[{"source": "https://ostergotlandsmuseum.se/upplev/vaegen-hit-i-mobilen/paalbyggnad-ca-3000-fvt/", "url": "https://ostergotlandsmuseum.se/upplev/vaegen-hit-i-mobilen/paalbyggnad-ca-3000-fvt/", "quote": "Pålbyggnad ca 3000 f.v.t.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Alvastra_pile-dwelling", "url": "https://en.wikipedia.org/wiki/Alvastra_pile-dwelling", "quote": "from ca 3000 BC", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0136)", "decision": "replace", "status": "MISSING", "reasoning": "Östergötlands museum and English Wikipedia both date the construction of the Alvastra pile dwelling to c. 3000 BC. That lies in the 3000-1500 BC bucket, not the stored 4500-3000 BC one, so -4500 is replaced by -3000.", "value_page": null}]'::jsonb),
    ('5583b792-3239-4362-a627-1923a30356dc'::uuid, 'site_type', 'Religious', 'City/town/settlement', 'fields-wd1-2026-09-26b-s004-rollback:5583b792-3239-4362-a627-1923a30356dc:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''City/town/settlement'' restored on Alvastra Pile-Dwelling', '[{"source": "https://en.wikipedia.org/wiki/Alvastra_pile-dwelling", "url": "https://en.wikipedia.org/wiki/Alvastra_pile-dwelling", "quote": "It was the seasonal social and religious centre of a tribe that left objects from the", "outcome": "found"}, {"source": "https://uddautflykter.se/guide/ostergotland/alvastra-palbyggnad/", "url": "https://uddautflykter.se/guide/ostergotland/alvastra-palbyggnad/", "quote": "Man vet att det inte var en försvarsanläggning och inte heller en vanlig boplats. Istället tror arkeologerna att det var en rituell kultplats där människor från trattbägarkulturen och den gropkeramiska kulturen möttes för att offra.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0136)", "decision": "replace", "status": "MISSING", "reasoning": "The sources describe the pile dwelling not as a settlement but as a seasonal cult place: Wikipedia calls it the tribe''s social and religious centre, Udda Utflykter says it was neither a fortification nor an ordinary settlement but a ritual cult site where people met to make offerings. City/town/settlement is therefore replaced by Religious.", "value_page": null}]'::jsonb),
    ('55d6f958-6ee7-4a0a-9e3c-23bbdb63d571'::uuid, 'site_type', 'Tomb', 'Megalithic statues', 'fields-wd1-2026-09-26b-s004-rollback:55d6f958-6ee7-4a0a-9e3c-23bbdb63d571:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Megalithic statues'' restored on Mount Nemrut', '[{"source": "https://www.livius.org/articles/place/nemrud-dagi/", "url": "https://www.livius.org/articles/place/nemrud-dagi/", "quote": "Nemrud Daği: the tomb of king Antiochus I Theos of Commagene (r.70-31 BCE), famous for its uncommon sculpture.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Mount_Nemrut", "url": "https://en.wikipedia.org/wiki/Mount_Nemrut", "quote": "notable for the summit where a number of large statues are erected around what is assumed to be a royal tomb from the 1st century BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0146)", "decision": "replace", "status": "CONFLICT", "reasoning": "Livius and Wikipedia describe the site as the royal tomb (tomb-sanctuary under a tumulus) of Antiochus I, with the colossal statues set on its terraces; the statues are Hellenistic sculpture, not megalithic, so Tomb is the type that holds the whole site.", "value_page": null}]'::jsonb),
    ('5604de42-1588-454f-8c49-893cc5044855'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s004-rollback:5604de42-1588-454f-8c49-893cc5044855:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''1 - 500 AD'' restored on Intini Uyu Pata', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5604de42-1588-454f-8c49-893cc5044855'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s004-rollback:5604de42-1588-454f-8c49-893cc5044855:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''1'' restored on Intini Uyu Pata', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0110)", "decision": "clear", "status": "MISSING", "reasoning": "MINCETUR assigns the site only to the Colla kingdom of the Lupaca (Aymara), and Wikipedia and the tourism pages give no date. The dates they print (formal discovery 1996, fitting-out 1997) are modern. With no attested start year, century or millennium, the stored 1 AD is cleared.", "value_page": null}]'::jsonb),
