    ('5639ccb8-8d69-4268-b4f1-5d52245214da'::uuid, 'period_start', NULL, '-3000', 'fields-wd1-2026-09-26b-s004-rollback:5639ccb8-8d69-4268-b4f1-5d52245214da:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-3000'' restored on Cappadocia', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0142)", "decision": "clear", "status": "MISSING", "reasoning": "A region has no construction, foundation or first-occupation date of its own; no source dates a site called Cappadocia, and the stored 3000 BC has no support, so the field is emptied.", "value_page": null}]'::jsonb),
    ('5639ccb8-8d69-4268-b4f1-5d52245214da'::uuid, 'site_type', NULL, 'Temple complex', 'fields-wd1-2026-09-26b-s004-rollback:5639ccb8-8d69-4268-b4f1-5d52245214da:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Temple complex'' restored on Cappadocia', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0142)", "decision": "clear", "status": "CONFLICT", "reasoning": "Wikipedia and Wikidata describe Cappadocia as a historical region, which none of the canonical site types holds, and no source describes it as a temple complex; the field is emptied.", "value_page": null}]'::jsonb),
    ('5639ccb8-8d69-4268-b4f1-5d52245214da'::uuid, 'source_url', NULL, 'https://en.wikipedia.org/wiki/Cappadocia', 'fields-wd1-2026-09-26b-s004-rollback:5639ccb8-8d69-4268-b4f1-5d52245214da:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/Cappadocia'' restored on Cappadocia', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0142)", "decision": "clear", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is about the region of Cappadocia; the entry points to no particular site within it, so no page about this very site can be named and the field is emptied.", "value_page": null}]'::jsonb),
    ('569f53de-6821-4597-b4f3-f695504b9d60'::uuid, 'period_name', '500 BC - 1 AD', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s004-rollback:569f53de-6821-4597-b4f3-f695504b9d60:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''1500 - 500 BC'' restored on Halliggye Fogou', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-500) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('569f53de-6821-4597-b4f3-f695504b9d60'::uuid, 'period_start', '-500', '-1500', 'fields-wd1-2026-09-26b-s004-rollback:569f53de-6821-4597-b4f3-f695504b9d60:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-1500'' restored on Halliggye Fogou', '[{"source": "https://www.cornwalls.co.uk/history/sites/halliggye.htm", "url": "https://www.cornwalls.co.uk/history/sites/halliggye.htm", "quote": "Located on the Trelowarren Estate, on the Lizard Peninsula, the site is believed to date back to the 5th century BC.", "outcome": "found"}, {"source": "https://www.english-heritage.org.uk/visit/places/halliggye-fogou/history/", "url": "https://www.english-heritage.org.uk/visit/places/halliggye-fogou/history/", "quote": "It is thought to have been constructed in the 5th or 4th centuries BC, in the middle Iron Age.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0035)", "decision": "replace", "status": "MISSING", "reasoning": "The Cornwall Guide dates the fogou to the 5th century BC and English Heritage, its guardian, says it was built in the 5th or 4th centuries BC; its start therefore falls at -500 (500 BC - 1 AD bucket), not in the stored 1500 - 500 BC bucket.", "value_page": null}]'::jsonb),
    ('569f53de-6821-4597-b4f3-f695504b9d60'::uuid, 'site_type', 'Cave Structures', 'Infrastructure', 'fields-wd1-2026-09-26b-s004-rollback:569f53de-6821-4597-b4f3-f695504b9d60:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Infrastructure'' restored on Halliggye Fogou', '[{"source": "https://www.english-heritage.org.uk/visit/places/halliggye-fogou/", "url": "https://www.english-heritage.org.uk/visit/places/halliggye-fogou/", "quote": "The purpose of such ‘fogous’ – a Cornish-language word meaning cave – is unknown, but they may have been places of refuge, storage chambers or ritual shrines.", "outcome": "found"}, {"source": "https://www.cornwalls.co.uk/history/sites/halliggye.htm", "url": "https://www.cornwalls.co.uk/history/sites/halliggye.htm", "quote": "Halliggye Fogou is a remarkably well-preserved underground tunnel dating back to the Iron Age.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0035)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is a fogou, a stone-built Iron Age underground passage whose Cornish name means cave (English Heritage, Cornwall Guide); ''Cave Structures'' is the canonical type for such artificial underground chambers, whereas ''Infrastructure'' describes nothing the sources say.", "value_page": null}]'::jsonb),
    ('56f3ec0c-0610-4701-8a4e-727b7d3a2512'::uuid, 'period_name', '500 BC - 1 AD', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s004-rollback:56f3ec0c-0610-4701-8a4e-727b7d3a2512:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''3000 - 1500 BC'' restored on Tumamoc Hill', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-500) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('56f3ec0c-0610-4701-8a4e-727b7d3a2512'::uuid, 'period_start', '-500', '-2100', 'fields-wd1-2026-09-26b-s004-rollback:56f3ec0c-0610-4701-8a4e-727b7d3a2512:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-2100'' restored on Tumamoc Hill', '[{"source": "https://aahs1916.org/2011/06/tumamoc-hill-with-the-fishes/", "url": "https://aahs1916.org/2011/06/tumamoc-hill-with-the-fishes/", "quote": "Tumamoc Hill just west of the Santa Cruz river in downtown Tucson is a trincheras site with occupations going back to 500 BC.", "outcome": "found"}, {"source": "https://tumamoc.org/timeline.html", "url": "https://tumamoc.org/timeline.html", "quote": "Indigenous peoples build a town on the mesa at the top of Tumamoc Hill during the Cienega phase (500 to 300 B.C.).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0150)", "decision": "replace", "status": "MISSING", "reasoning": "The stored -2100 is the start of the Early Agricultural period in the Tucson basin, not of the site; the hilltop village itself is dated to the Cienega phase, with occupation going back to 500 BC (AAHS, tumamoc.org), which lies in the 500 BC - 1 AD bucket.", "value_page": null}]'::jsonb),
    ('56f3ec0c-0610-4701-8a4e-727b7d3a2512'::uuid, 'site_type', 'Village', 'Petroglyphs', 'fields-wd1-2026-09-26b-s004-rollback:56f3ec0c-0610-4701-8a4e-727b7d3a2512:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Petroglyphs'' restored on Tumamoc Hill', '[{"source": "https://en.wikipedia.org/wiki/Tumamoc_Hill", "url": "https://en.wikipedia.org/wiki/Tumamoc_Hill", "quote": "It is the site of the earliest known trincheras village, consisting of 160 foundations of round stone structures", "outcome": "found"}, {"source": "https://www.tumamoc.org/research.html", "url": "https://www.tumamoc.org/research.html", "quote": "A 2300-yr old ruined village on the top of the mesa", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0025)", "decision": "replace", "status": "CONFLICT", "reasoning": "Tumamoc Hill is documented as a prehistoric hilltop trincheras village (160 house foundations inside massive stone walls); its petroglyphs (460 to about a thousand) are one feature among the village, walls and agave fields, so Petroglyphs is too narrow and Village is the site''s specific type.", "value_page": null}]'::jsonb),
