    ('574b24e0-9357-4d1a-a66b-556a0dfe6303'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s004-rollback:574b24e0-9357-4d1a-a66b-556a0dfe6303:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''1500 - 500 BC'' restored on Cadbury Hill', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('574b24e0-9357-4d1a-a66b-556a0dfe6303'::uuid, 'period_start', NULL, '-1000', 'fields-wd1-2026-09-26b-s004-rollback:574b24e0-9357-4d1a-a66b-556a0dfe6303:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-1000'' restored on Cadbury Hill', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0029)", "decision": "clear", "status": "MISSING", "reasoning": "The readable sources say only that the hill fort ''appears to have been constructed in the Iron Age'' without a year or century for this site; Wikipedia''s ''start of the 1st millennium BC'' refers to hill forts in general, so there are not two sources dating this site''s start.", "value_page": null}]'::jsonb),
    ('574b24e0-9357-4d1a-a66b-556a0dfe6303'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s004-rollback:574b24e0-9357-4d1a-a66b-556a0dfe6303:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Fortress/citadel'' restored on Cadbury Hill', '[{"source": "https://en.wikipedia.org/wiki/Cadbury_Hill", "url": "https://en.wikipedia.org/wiki/Cadbury_Hill", "quote": "On its summit stands an Iron Age hill fort", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=13163", "url": "https://www.megalithic.co.uk/article.php?sid=13163", "quote": "Type: Hillfort", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0029)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the Megalithic Portal describe the site as an Iron Age hill fort (hillfort), later refortified; the canonical type for a hillfort is Fort rather than Fortress/citadel.", "value_page": null}]'::jsonb),
    ('577f59ce-ea47-4d39-a1f0-c5a0fd6e84d1'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s004-rollback:577f59ce-ea47-4d39-a1f0-c5a0fd6e84d1:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''1500 - 500 BC'' restored on Brown Clee Hill', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('577f59ce-ea47-4d39-a1f0-c5a0fd6e84d1'::uuid, 'period_start', NULL, '-1000', 'fields-wd1-2026-09-26b-s004-rollback:577f59ce-ea47-4d39-a1f0-c5a0fd6e84d1:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-1000'' restored on Brown Clee Hill', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0028)", "decision": "clear", "status": "MISSING", "reasoning": "The Abdon Burf hillfort is almost entirely destroyed by quarrying; the sources call it Iron Age but give no year, century or millennium for its construction (the ''first millennium BC'' statements concern Nordy Bank, a different fort 2.8 km away), so nothing supports the stored -1000.", "value_page": null}]'::jsonb),
    ('577f59ce-ea47-4d39-a1f0-c5a0fd6e84d1'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s004-rollback:577f59ce-ea47-4d39-a1f0-c5a0fd6e84d1:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Fortress/citadel'' restored on Brown Clee Hill', '[{"source": "https://en.wikipedia.org/wiki/Brown_Clee_Hill", "url": "https://en.wikipedia.org/wiki/Brown_Clee_Hill", "quote": "The common land features the remains of where an Iron Age hill fort once stood", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=11447", "url": "https://www.megalithic.co.uk/article.php?sid=11447", "quote": "Looking at the summit of Brown Clee Hill - home to the remains of Abdon Burf hillfort; this is nearly completely destroyed from quarrying.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0028)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources describe the monument on the summit of Brown Clee Hill as an Iron Age hillfort (Abdon Burf); Fort fits a hillfort better than Fortress/citadel.", "value_page": null}]'::jsonb),
    ('577f59ce-ea47-4d39-a1f0-c5a0fd6e84d1'::uuid, 'source_url', 'https://www.megalithic.co.uk/article.php?sid=11447', 'https://en.wikipedia.org/wiki/Brown_Clee_Hill', 'fields-wd1-2026-09-26b-s004-rollback:577f59ce-ea47-4d39-a1f0-c5a0fd6e84d1:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/Brown_Clee_Hill'' restored on Brown Clee Hill', '[{"source": "https://www.megalithic.co.uk/article.php?sid=11447", "url": "https://www.megalithic.co.uk/article.php?sid=11447", "quote": "Looking at the summit of Brown Clee Hill - home to the remains of Abdon Burf hillfort; this is nearly completely destroyed from quarrying.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Brown_Clee_Hill", "url": "https://en.wikipedia.org/wiki/Brown_Clee_Hill", "quote": "The other two, at Abdon Burf and Clee Burf, have been largely lost to quarrying activity.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0028)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the hill; the hillfort at the stored point, Abdon Burf, has no article of its own, and the Megalithic Portal''s Abdon Burf Hillfort page is about the site itself and loads as plain HTML.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('57ced914-514c-4de1-97d9-63e5c23e3bc3'::uuid, 'period_name', NULL, '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s004-rollback:57ced914-514c-4de1-97d9-63e5c23e3bc3:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''4500 - 3000 BC'' restored on Beacon Hill, Leicestershire', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('57ced914-514c-4de1-97d9-63e5c23e3bc3'::uuid, 'period_start', NULL, '-4500', 'fields-wd1-2026-09-26b-s004-rollback:57ced914-514c-4de1-97d9-63e5c23e3bc3:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-4500'' restored on Beacon Hill, Leicestershire', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0026)", "decision": "clear", "status": "MISSING", "reasoning": "The hillfort has never been excavated; the scheduling text, Wikipedia and the Megalithic Portal call it Bronze Age or Late Bronze Age from a founder''s hoard found in 1858, but no readable source gives a year, century or millennium for its start, and the stored -4500 (Neolithic bucket) has no support; the field is emptied.", "value_page": null}]'::jsonb),
    ('57ced914-514c-4de1-97d9-63e5c23e3bc3'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s004-rollback:57ced914-514c-4de1-97d9-63e5c23e3bc3:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Fortress/citadel'' restored on Beacon Hill, Leicestershire', '[{"source": "https://en.wikipedia.org/wiki/Beacon_Hill,_Leicestershire", "url": "https://en.wikipedia.org/wiki/Beacon_Hill,_Leicestershire", "quote": "Beacon Hill was the site of a Bronze Age hill fort.", "outcome": "found"}, {"source": "https://www.charnwood.gov.uk/listed_buildings/hill_fort_enclosure_and_linear_boundary_beacon_hill_woodhouse", "url": "https://www.charnwood.gov.uk/listed_buildings/hill_fort_enclosure_and_linear_boundary_beacon_hill_woodhouse", "quote": "The monument at Beacon Hill is situated on the Charnwood uplands north west of Leicester and includes a slight univallate hillfort a linear boundary and an enclosure which is contained in a second area.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=7855", "url": "https://www.megalithic.co.uk/article.php?sid=7855", "quote": "Country: England County: Leicestershire and Rutland Type: Hillfort", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0026)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia, the scheduled-monument description on Charnwood Borough Council''s heritage list and the Megalithic Portal describe the site as a (slight univallate) hillfort; Fort is the specific type, rather than Fortress/citadel.", "value_page": null}]'::jsonb),
    ('57ced914-514c-4de1-97d9-63e5c23e3bc3'::uuid, 'source_url', 'https://www.charnwood.gov.uk/listed_buildings/hill_fort_enclosure_and_linear_boundary_beacon_hill_woodhouse', 'https://en.wikipedia.org/wiki/Beacon_Hill,_Leicestershire', 'fields-wd1-2026-09-26b-s004-rollback:57ced914-514c-4de1-97d9-63e5c23e3bc3:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/Beacon_Hill,_Leicestershire'' restored on Beacon Hill, Leicestershire', '[{"source": "https://www.charnwood.gov.uk/listed_buildings/hill_fort_enclosure_and_linear_boundary_beacon_hill_woodhouse", "url": "https://www.charnwood.gov.uk/listed_buildings/hill_fort_enclosure_and_linear_boundary_beacon_hill_woodhouse", "quote": "Hill Fort, Enclosure and Linear Boundary, Beacon Hill, Woodhouse", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=7855", "url": "https://www.megalithic.co.uk/article.php?sid=7855", "quote": "Beacon Hill (Leicestershire) Hillfort Leicestershire and Rutland", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0026)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the hill and country park; Charnwood Borough Council''s entry for the scheduled monument (Monument Number 17111) is about the hillfort itself and loads as plain HTML, unlike the Historic England list.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('57ded976-9874-4832-8716-2b54c1fee102'::uuid, 'site_type', 'Dolmen', 'Necropolis/tombs complex', 'fields-wd1-2026-09-26b-s004-rollback:57ded976-9874-4832-8716-2b54c1fee102:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Necropolis/tombs complex'' restored on Table des Marchand', '[{"source": "https://fr.wikipedia.org/wiki/Table_des_Marchands", "url": "https://fr.wikipedia.org/wiki/Table_des_Marchands", "quote": "La Table des Marchands est un dolmen situé sur le site mégalithique de Locmariaquer", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=9313", "url": "https://www.megalithic.co.uk/article.php?sid=9313", "quote": "Type: Burial Chamber or Dolmen", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0055)", "decision": "replace", "status": "MISSING", "reasoning": "Both sources describe the Table des Marchands as a single dolmen (passage grave), not a necropolis complex, so the more specific type Dolmen holds.", "value_page": null}]'::jsonb),
    ('58286d95-1d76-4513-b5ca-dc386c3033a8'::uuid, 'period_name', '1500 - 500 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s004-rollback:58286d95-1d76-4513-b5ca-dc386c3033a8:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''3000 - 1500 BC'' restored on The Lost City of Heracleion', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-800) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('58286d95-1d76-4513-b5ca-dc386c3033a8'::uuid, 'period_start', '-800', '-3000', 'fields-wd1-2026-09-26b-s004-rollback:58286d95-1d76-4513-b5ca-dc386c3033a8:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-3000'' restored on The Lost City of Heracleion', '[{"source": "https://www.franckgoddio.org/projects/sunken-civilizations/heracleion", "url": "https://www.franckgoddio.org/projects/sunken-civilizations/heracleion", "quote": "The city was founded probably around the 8th century BC, underwent diverse natural catastrophes, and finally sunk entirely into the depths of the Mediterranean in the 8th century AD.", "outcome": "found"}, {"source": "https://allthatsinteresting.com/thonis-heracleion", "url": "https://allthatsinteresting.com/thonis-heracleion", "quote": "Likely founded around the 8th century B.C.E., Thonis-Heracleion long reigned as Egypt''s most important port.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0025)", "decision": "replace", "status": "MISSING", "reasoning": "The excavator Franck Goddio (IEASM) dates the foundation of Thonis-Heracleion to around the 8th century BC, and All That''s Interesting also puts its founding around the 8th century BCE; the Wikipedia 12th-century BC date is explicitly only ''legendary''. The attested start lies in the 1500 - 500 BC bucket, not the stored 3000 - 1500 BC one.", "value_page": null}]'::jsonb),
