    ('585ae9f5-c9ef-4446-84e9-a2c5825f5eda'::uuid, 'site_type', 'Tomb', 'Necropolis/tombs complex', 'fields-wd1-2026-09-26b-s004-rollback:585ae9f5-c9ef-4446-84e9-a2c5825f5eda:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Necropolis/tombs complex'' restored on Twin Column Tomb', '[{"source": "https://en.wikipedia.org/wiki/Twin_Column_Tomb", "url": "https://en.wikipedia.org/wiki/Twin_Column_Tomb", "quote": "is a two-chambered burial tomb dating from Koguryo period. It is located in", "outcome": "found"}, {"source": "https://portal.nrich.go.kr/kor/archeologyUsrView.do?menuIdx=567&idx=11139", "url": "https://portal.nrich.go.kr/kor/archeologyUsrView.do?menuIdx=567&idx=11139", "quote": "평안남도 남포시 용강군 용강읍(舊地名 : 평남 용강군 지운면 진지동)에 위치한 고구려 벽화고분으로", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0100)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia describes the site as a single two-chambered burial tomb and the Korean heritage institute as a Goguryeo mural tomb (byeokhwa gobun) in Ryonggang; it is one tomb, not a necropolis or tomb complex.", "value_page": null}]'::jsonb),
