    ('5860ecf2-57f8-44e6-93a1-0f6b5d6994e1'::uuid, 'period_start', '900', '1', 'fields-wd1-2026-09-26b-s004-rollback:5860ecf2-57f8-44e6-93a1-0f6b5d6994e1:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''1'' restored on Isla Palenque', '[{"source": "https://scottdpalumbo.wixsite.com/chiriqui/blank-4", "url": "https://scottdpalumbo.wixsite.com/chiriqui/blank-4", "quote": "The site is believed to date to between 900 and 1100 A.D., which is a period of time associated with increased demographic growth", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Isla_Palenque", "url": "https://en.wikipedia.org/wiki/Isla_Palenque", "quote": "was the home of an ancient, pre-Columbian farming community some time during the years 500-1400AD.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0105)", "decision": "replace", "status": "MISSING", "reasoning": "The Chiriqui Archaeological Project excavating La Pitahaya on Isla Palenque dates the site to 900-1100 AD, and Wikipedia (after Linares) puts the pre-Columbian community within 500-1400 AD; both starts fall in the bucket 500 - 1000 AD, not the stored 1 AD.", "value_page": null}]'::jsonb),
