    ('589b9ba5-10a2-4138-b3bb-03d45ddeb614'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Dundon_Hill_Hillfort', 'https://en.wikipedia.org/wiki/Compton_Dundon', 'fields-wd1-2026-09-26b-s004-rollback:589b9ba5-10a2-4138-b3bb-03d45ddeb614:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/Compton_Dundon'' restored on Compton Dundon', '[{"source": "https://en.wikipedia.org/wiki/Dundon_Hill_Hillfort", "url": "https://en.wikipedia.org/wiki/Dundon_Hill_Hillfort", "quote": "Dundon Hill Hillfort is an Iron Age hillfort in Compton Dundon, Somerset, England.", "outcome": "found"}, {"source": "https://brigantesnation.com/sites/world-heritage/somerset/dundon-hill-fort/", "url": "https://brigantesnation.com/sites/world-heritage/somerset/dundon-hill-fort/", "quote": "Dundon Hill Hillfort, located near Compton Dundon in Somerset, is a univallate (single-ditch) hillfort", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0032)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored article is about the village and parish of Compton Dundon; the hillfort has its own English Wikipedia article, Dundon Hill Hillfort, which is about this very site, so the source is replaced by it.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Dundon Hill Hillfort", "unreadable": false, "wikibase_item": "Q5314880"}}]'::jsonb),
