    ('58a2be59-ec1e-4667-96b9-3313ce406bc1'::uuid, 'period_start', '1866', '-3500', 'fields-wd1-2026-09-26b-s004-rollback:58a2be59-ec1e-4667-96b9-3313ce406bc1:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-3500'' restored on Font dels Coms', '[{"source": "https://www.bondia.ad/vist-i-no-vist/font-dels-coms-anys-40", "url": "https://www.bondia.ad/vist-i-no-vist/font-dels-coms-anys-40", "quote": "Construïda el 1866 a l''antic camí ral, avui Doctor Palau, a Sant Julià.", "outcome": "found"}, {"source": "https://evendo.com/locations/andorra/sant-julia-de-loria/attraction/la-font-del-coms", "url": "https://evendo.com/locations/andorra/sant-julia-de-loria/attraction/la-font-del-coms", "quote": "Dating back to 1866, this modest yet beautiful fountain served as a vital watering spot for villagers and muleteers", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0005)", "decision": "replace", "status": "MISSING", "reasoning": "The Andorran newspaper Bondia says the fountain was built in 1866 (its millstone bears the inscription ''G. Y AP 1866''), and Evendo also dates it to 1866; the stored -3500 has no basis.", "value_page": null}]'::jsonb),
    ('58a2be59-ec1e-4667-96b9-3313ce406bc1'::uuid, 'site_type', 'Heritage site', 'Geological interest', 'fields-wd1-2026-09-26b-s004-rollback:58a2be59-ec1e-4667-96b9-3313ce406bc1:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Geological interest'' restored on Font dels Coms', '[{"source": "https://travelshelper.com/andorra/sant-julia-de-loria/la-font-del-coms/", "url": "https://travelshelper.com/andorra/sant-julia-de-loria/la-font-del-coms/", "quote": "It is a small streetside heritage feature rather than a destination requiring a ticket or long visit", "outcome": "found"}, {"source": "https://evendo.com/locations/andorra/sant-julia-de-loria/attraction/la-font-del-coms", "url": "https://evendo.com/locations/andorra/sant-julia-de-loria/attraction/la-font-del-coms", "quote": "a historical landmark offering a serene glimpse into Andorra''s rich cultural heritage and communal past", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0005)", "decision": "replace", "status": "MISSING", "reasoning": "The sources describe a historic 19th-century public fountain built from a reused millstone, a man-made heritage feature, not a geological one; no canonical type names a fountain, so the generic Heritage site applies.", "value_page": null}]'::jsonb),
    ('58a2be59-ec1e-4667-96b9-3313ce406bc1'::uuid, 'source_url', 'https://visitandorra.com/en/points-of-interest/font-dels-coms-spring/', 'https://visitandorra.com/en/culture/font-dels-coms-spring/', 'fields-wd1-2026-09-26b-s004-rollback:58a2be59-ec1e-4667-96b9-3313ce406bc1:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://visitandorra.com/en/culture/font-dels-coms-spring/'' restored on Font dels Coms', '[{"source": "https://visitandorra.com/en/points-of-interest/font-dels-coms-spring/", "url": "https://visitandorra.com/en/points-of-interest/font-dels-coms-spring/", "quote": "Font dels Cóms spring", "outcome": "found"}, {"source": "https://www.bondia.ad/vist-i-no-vist/font-dels-coms-anys-40", "url": "https://www.bondia.ad/vist-i-no-vist/font-dels-coms-anys-40", "quote": "Font dels Cóms, anys 40", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0005)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Visit Andorra URL redirects to its current address, the official tourism page on this fountain in Sant Julià de Lòria; the resolved URL replaces the redirect, and Bondia independently names the same fountain.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('58b67d2b-fb58-41b0-b7d3-16c36ca4507a'::uuid, 'period_name', NULL, '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s004-rollback:58b67d2b-fb58-41b0-b7d3-16c36ca4507a:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''3000 - 1500 BC'' restored on Foel Fenlli', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('58b67d2b-fb58-41b0-b7d3-16c36ca4507a'::uuid, 'period_start', NULL, '-3000', 'fields-wd1-2026-09-26b-s004-rollback:58b67d2b-fb58-41b0-b7d3-16c36ca4507a:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-3000'' restored on Foel Fenlli', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0153)", "decision": "clear", "status": "MISSING", "reasoning": "The construction date of the hillfort is unknown: Cadw only says such monuments probably date to the Iron Age (c. 800 BC - AD 74) or the Late Bronze Age, Heather and Hillforts says around 2,500 years ago, and the Welsh Wikipedia dates the defences to the 1st century BC to the 4th century AD, so no two independent sources give the same year and nothing supports the stored 3000 BC.", "value_page": null}]'::jsonb),
    ('58b67d2b-fb58-41b0-b7d3-16c36ca4507a'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s004-rollback:58b67d2b-fb58-41b0-b7d3-16c36ca4507a:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Fortress/citadel'' restored on Foel Fenlli', '[{"source": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=386", "url": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=386", "quote": "Moel Fenlli comprises the remains of a hillfort.", "outcome": "found"}, {"source": "https://coflein.gov.uk/en/sites/96522", "url": "https://coflein.gov.uk/en/sites/96522", "quote": "A vast 9.8ha hillfort crowns the summit of Foel Fenlli, a mountain peak overlooking the vale of Clwyd. The fort is rather irregular in shape, roughly 480m east-west by 74-280m.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0153)", "decision": "replace", "status": "CONFLICT", "reasoning": "Cadw (site type Hillfort) and Coflein (type HILLFORT) both describe a hillfort, not a fortress or citadel; Fort is the canonical type for a hillfort.", "value_page": null}]'::jsonb),
    ('58b67d2b-fb58-41b0-b7d3-16c36ca4507a'::uuid, 'source_url', 'https://coflein.gov.uk/en/sites/96522', 'https://en.wikipedia.org/wiki/Foel_Fenlli', 'fields-wd1-2026-09-26b-s004-rollback:58b67d2b-fb58-41b0-b7d3-16c36ca4507a:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/Foel_Fenlli'' restored on Foel Fenlli', '[{"source": "https://coflein.gov.uk/en/sites/96522", "url": "https://coflein.gov.uk/en/sites/96522", "quote": "Foel Fenlli Hillfort", "outcome": "found"}, {"source": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=386", "url": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=386", "quote": "Reference Number DE009 Name Moel Fenlli Camp", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0153)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is filed as a hill (Marilyn) with the hillfort in one section; Coflein''s record NPRN 96522 (Foel Fenlli Hillfort) and Cadw''s report DE009 (Moel Fenlli Camp) are about the hillfort itself.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('58bdf3b7-f210-49b4-bc02-f060c120737a'::uuid, 'period_name', '500 BC - 1 AD', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s004-rollback:58bdf3b7-f210-49b4-bc02-f060c120737a:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''3000 - 1500 BC'' restored on El Cerrito', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-300) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('58bdf3b7-f210-49b4-bc02-f060c120737a'::uuid, 'period_start', '-300', '-3000', 'fields-wd1-2026-09-26b-s004-rollback:58bdf3b7-f210-49b4-bc02-f060c120737a:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-3000'' restored on El Cerrito', '[{"source": "https://sic.cultura.gob.mx/ficha.php?table=zona_arqueologica&table_id=85", "url": "https://sic.cultura.gob.mx/ficha.php?table=zona_arqueologica&table_id=85", "quote": "Cronología: 300 a. C. a siglo XVII.", "outcome": "found"}, {"source": "https://sic.cultura.gob.mx/ficha.php?table=zona_arqueologica&table_id=85", "url": "https://sic.cultura.gob.mx/ficha.php?table=zona_arqueologica&table_id=85", "quote": "Su ocupación fue continua desde el Preclásico Superior hasta el siglo XVII.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/El_Cerrito_(archaeological_site)", "url": "https://en.wikipedia.org/wiki/El_Cerrito_(archaeological_site)", "quote": "Since 300 BCE, The Chupícuaro culture settled in the region", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0095)", "decision": "replace", "status": "CONFLICT", "reasoning": "Mexico''s Ministry of Culture register gives El Cerrito a chronology from 300 BC to the 17th century, with continuous occupation from the Late Preclassic. Wikipedia likewise dates the Chupícuaro settlement to 300 BCE. The start, 300 BC, lies in the 500 BC - 1 AD bucket, so the stored -3000 (3000 - 1500 BC) is wrong. INAH''s visitor page is later still (''early years of the first millennium AD''), but no source supports a 3rd- or 2nd-millennium BC start.", "value_page": null}]'::jsonb),
    ('593de422-8bfc-4101-8e13-3db406830e60'::uuid, 'period_name', '1500 - 500 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s004-rollback:593de422-8bfc-4101-8e13-3db406830e60:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''3000 - 1500 BC'' restored on Didnauri', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1200) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('593de422-8bfc-4101-8e13-3db406830e60'::uuid, 'period_start', '-1200', '-3000', 'fields-wd1-2026-09-26b-s004-rollback:593de422-8bfc-4101-8e13-3db406830e60:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-3000'' restored on Didnauri', '[{"source": "https://en.wikipedia.org/wiki/Didnauri", "url": "https://en.wikipedia.org/wiki/Didnauri", "quote": "Preliminary digs revealed ruins of a large settlement, which was dated by a team of Georgian archaeologists to the period of 12th to 9th century BC.", "outcome": "found"}, {"source": "https://sciencepublishinggroup.com/article/10.11648/j.ija.20261402.12", "url": "https://sciencepublishinggroup.com/article/10.11648/j.ija.20261402.12", "quote": "Archaeological investigations date Didnauri mainly to the 12th-9th centuries BCE", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0056)", "decision": "replace", "status": "MISSING", "reasoning": "English Wikipedia and the excavator Pitskhelauri''s 2026 paper both date the settlement to the 12th-9th centuries BC, so it begins in the 12th century BC (-1200). That is in the 1500 - 500 BC bucket, not the stored 3000 - 1500 BC one.", "value_page": null}]'::jsonb),
