    ('59af6742-7a6d-45ba-9cb7-9fd0de0c51c9'::uuid, 'site_type', 'Archaeological site', 'City/town/settlement', 'fields-wd1-2026-09-26b-s004-rollback:59af6742-7a6d-45ba-9cb7-9fd0de0c51c9:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''City/town/settlement'' restored on Casma-Sechin Culture', '[{"source": "https://en.wikipedia.org/wiki/Casma%E2%80%93Sechin_culture", "url": "https://en.wikipedia.org/wiki/Casma%E2%80%93Sechin_culture", "quote": "The ruins include major archaeological sites such as Sechin Bajo", "outcome": "found"}, {"source": "https://www.perunorth.com/sechin", "url": "https://www.perunorth.com/sechin", "quote": "The complex covers around 10.5 square km (4 sq. miles) and includes four separate sites", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0106)", "decision": "replace", "status": "CONFLICT", "reasoning": "The entry names a culture whose remains are a group of separate archaeological sites (Sechin Bajo, Sechin Alto, Cerro Sechin, Taukachi-Konkan, Chankillo and others) of different kinds, not one town; no specific type holds for the whole, so the generic Archaeological site replaces City/town/settlement.", "value_page": null}]'::jsonb),
    ('59f8faa5-2f0f-4278-9c2c-97c4adaa55b7'::uuid, 'site_type', 'Sacred site', 'Archaeological site', 'fields-wd1-2026-09-26b-s004-rollback:59f8faa5-2f0f-4278-9c2c-97c4adaa55b7:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Archaeological site'' restored on Fontes Tamarici', '[{"source": "https://en.wikipedia.org/wiki/Fontes_Tamarici", "url": "https://en.wikipedia.org/wiki/Fontes_Tamarici", "quote": "inhabited the area from the 3rd century BC. They worshiped waters and the sacred springs.", "outcome": "found"}, {"source": "https://blogs.deia.eus/cuentos-peregrinos/2023/01/04/la-fuente-de-la-reana-de-velilla-del-rio-carrion-el-manantial-sagrado-de-las-antiguas-tribus-tamaricas-cantabras/", "url": "https://blogs.deia.eus/cuentos-peregrinos/2023/01/04/la-fuente-de-la-reana-de-velilla-del-rio-carrion-el-manantial-sagrado-de-las-antiguas-tribus-tamaricas-cantabras/", "quote": "Estas aguas se consideraban como el manantial sagrado de las antiguas tribus de la Cantabria", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0131)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Fontes Tamarici are intermittent springs with a Roman stone pool that the Cantabrians venerated as a sacred, oracular spring (Pliny''s omen), later Christianised by a hermitage; Sacred site is more specific than the generic Archaeological site.", "value_page": null}]'::jsonb),
    ('5a04c048-e207-42fe-9d26-b39a0217bf09'::uuid, 'period_name', '3000 - 1500 BC', '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s004-rollback:5a04c048-e207-42fe-9d26-b39a0217bf09:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''4500 - 3000 BC'' restored on Knowlton Circles', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-3000) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5a04c048-e207-42fe-9d26-b39a0217bf09'::uuid, 'period_start', '-3000', '-4500', 'fields-wd1-2026-09-26b-s004-rollback:5a04c048-e207-42fe-9d26-b39a0217bf09:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-4500'' restored on Knowlton Circles', '[{"source": "https://heritage.dorsetcouncil.gov.uk/Monument/MDO6416", "url": "https://heritage.dorsetcouncil.gov.uk/Monument/MDO6416", "quote": "HENGE (Late Neolithic to Early Bronze Age - 3000 BC to 1501 BC)", "outcome": "found"}, {"source": "https://eprints.bournemouth.ac.uk/30482/3/GALEKNOWLTON_AOM.pdf", "url": "https://eprints.bournemouth.ac.uk/30482/3/GALEKNOWLTON_AOM.pdf", "quote": "At around the middle of the 3rd millennium BC and possibly as early as 2800 BC a succession", "outcome": "found"}, {"source": "https://www.english-heritage.org.uk/visit/places/knowlton-church-and-earthworks/history/", "url": "https://www.english-heritage.org.uk/visit/places/knowlton-church-and-earthworks/history/", "quote": "The main earthwork at Knowlton is of a type known as a henge. There are nearly one hundred henges in Britain and Ireland, dating from about 3000 to 2000 BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0038)", "decision": "replace", "status": "MISSING", "reasoning": "The Dorset HER classes Church Henge as a Late Neolithic to Early Bronze Age henge (3000 BC to 1501 BC), Gale''s Bournemouth University review dates the construction of the Knowlton henges to the 3rd millennium BC (around its middle, possibly as early as 2800 BC), and English Heritage dates the henge type to about 3000-2000 BC; no source attests activity before 3000 BC, so the start moves from the 4500 - 3000 BC bucket to the 3rd millennium BC, -3000.", "value_page": null}]'::jsonb),
    ('5a91fe47-3207-443c-9eff-a1afd9e47481'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s004-rollback:5a91fe47-3207-443c-9eff-a1afd9e47481:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''1 - 500 AD'' restored on Maiden Way', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5a91fe47-3207-443c-9eff-a1afd9e47481'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s004-rollback:5a91fe47-3207-443c-9eff-a1afd9e47481:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''1'' restored on Maiden Way', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0040)", "decision": "clear", "status": "MISSING", "reasoning": "No source dates the road''s construction: Wikipedia, Roman-Britain.co.uk, Is this a Roman road? and the Cumbria Roman-roads gazetteer describe its route but give no year or century, and Epiacum Heritage dates only the fort it passes (''built at about the same time as Hadrian''s Wall''), not the road itself.", "value_page": null}]'::jsonb),
    ('5ae9fc36-4419-4e08-aa2d-a7653a46cafe'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s004-rollback:5ae9fc36-4419-4e08-aa2d-a7653a46cafe:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''1 - 500 AD'' restored on Huiñao', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5ae9fc36-4419-4e08-aa2d-a7653a46cafe'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s004-rollback:5ae9fc36-4419-4e08-aa2d-a7653a46cafe:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''1'' restored on Huiñao', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0109)", "decision": "clear", "status": "MISSING", "reasoning": "The only description of the ruins (MINCETUR''s inventory, mirrored by turismoperuano.com) calls them pre-Inca and ''probably'' Wari without any date, and no other source dates the site; the stored 1 AD is unsupported, so the field is emptied.", "value_page": null}]'::jsonb),
    ('5ae9fc36-4419-4e08-aa2d-a7653a46cafe'::uuid, 'site_type', 'Archaeological site', 'City/town/settlement', 'fields-wd1-2026-09-26b-s004-rollback:5ae9fc36-4419-4e08-aa2d-a7653a46cafe:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''City/town/settlement'' restored on Huiñao', '[{"source": "https://en.wikipedia.org/wiki/Hui%C3%B1ao", "url": "https://en.wikipedia.org/wiki/Hui%C3%B1ao", "quote": "There is also an archaeological site on top of the mountain.", "outcome": "found"}, {"source": "https://www.turismoperuano.com/cerro-huinao-arequipa", "url": "https://www.turismoperuano.com/cerro-huinao-arequipa", "quote": "en la cima se encuentran las construcciones pre incas de Cochacallan, probablemente de la cultura Wari, que abarcan un área aproximada de 100m2, que se encuentran en abandono.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0109)", "decision": "replace", "status": "CONFLICT", "reasoning": "The sources describe only an archaeological site of abandoned pre-Inca constructions covering about 100 m2 on the summit, far too small and unspecified to be a City/town/settlement; no more specific type is attested, so the generic Archaeological site replaces it.", "value_page": null}]'::jsonb),
    ('5af64ae1-13fb-4693-a070-fa3628f8f78e'::uuid, 'period_name', '1500+ AD', '1 - 500 AD', 'fields-wd1-2026-09-26b-s004-rollback:5af64ae1-13fb-4693-a070-fa3628f8f78e:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''1 - 500 AD'' restored on San Lorenzo Tenochtitlán Museum', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(1986) = ''1500+ AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5af64ae1-13fb-4693-a070-fa3628f8f78e'::uuid, 'period_start', '1986', '1', 'fields-wd1-2026-09-26b-s004-rollback:5af64ae1-13fb-4693-a070-fa3628f8f78e:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''1'' restored on San Lorenzo Tenochtitlán Museum', '[{"source": "https://lugares.inah.gob.mx/en/node/4513", "url": "https://lugares.inah.gob.mx/en/node/4513", "quote": "It opened as a community museum in 1986 and was designated the site museum of San Lorenzo Tenochtitlan in May 1995.", "outcome": "found"}, {"source": "https://sic.gob.mx/ficha.php?table=museo&table_id=555", "url": "https://sic.gob.mx/ficha.php?table=museo&table_id=555", "quote": "Este espacio se abrió al público el 1 de mayo de 1995", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0097)", "decision": "replace", "status": "MISSING", "reasoning": "This entry is the site museum, not the Olmec city: INAH says it opened as a community museum in 1986 and became the INAH site museum in May 1995, and the Secretaría de Cultura''s SIC dates its public opening to 1 May 1995; both put the start in the 1500+ AD bucket, and 1986 is the first opening.", "value_page": null}]'::jsonb),
    ('5b103764-5dfc-42b8-8d6b-6617495f7230'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s004-rollback:5b103764-5dfc-42b8-8d6b-6617495f7230:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''1500 - 500 BC'' restored on Caer Caradoc - Chapel Lawn', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5b103764-5dfc-42b8-8d6b-6617495f7230'::uuid, 'period_start', NULL, '-1500', 'fields-wd1-2026-09-26b-s004-rollback:5b103764-5dfc-42b8-8d6b-6617495f7230:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-1500'' restored on Caer Caradoc - Chapel Lawn', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0029)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia and the Megalithic Portal call Caer Caradoc near Chapel Lawn an Iron Age hill fort but give no year or century for its construction, and the Historic England entry cannot be read, so no two independent sources date its start.", "value_page": null}]'::jsonb),
    ('5b36f014-cb4a-4c2f-84b3-80996c503702'::uuid, 'period_name', '1000 - 1500 AD', '1 - 500 AD', 'fields-wd1-2026-09-26b-s004-rollback:5b36f014-cb4a-4c2f-84b3-80996c503702:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''1 - 500 AD'' restored on Kłopot, Lubusz Voivodeship', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(1201) = ''1000 - 1500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5b36f014-cb4a-4c2f-84b3-80996c503702'::uuid, 'period_start', '1201', '1', 'fields-wd1-2026-09-26b-s004-rollback:5b36f014-cb4a-4c2f-84b3-80996c503702:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''1'' restored on Kłopot, Lubusz Voivodeship', '[{"source": "https://en.wikipedia.org/wiki/K%C5%82opot,_Lubusz_Voivodeship", "url": "https://en.wikipedia.org/wiki/K%C5%82opot,_Lubusz_Voivodeship", "quote": "The current settlement was formed in the early 13th century.", "outcome": "found"}, {"source": "https://ziemialubuska.pl/pl/lokalnie/powiaty-i-gminy/powiat-slubicki/cybinka-gmina/klopot", "url": "https://ziemialubuska.pl/pl/lokalnie/powiaty-i-gminy/powiat-slubicki/cybinka-gmina/klopot", "quote": "Wieś pierwszy raz wzmiankowana w 1350 roku. Powstała niewątpliwie w pierwszej połowie XIII wieku.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0116)", "decision": "replace", "status": "MISSING", "reasoning": "English Wikipedia (citing the Cybinka municipality) and the regional portal Ziemia Lubuska both date the village''s foundation to the first half of the 13th century; it is first mentioned in 1350. The three archaeological sites both sources mention are dated only to the Early Middle Ages, and nothing attests activity in 1 - 500 AD, so the start is replaced with 1201, the first year of the 13th century.", "value_page": null}]'::jsonb),
    ('5b4a848a-90b8-432e-9016-d931607218cd'::uuid, 'period_name', NULL, '1000 - 1500 AD', 'fields-wd1-2026-09-26b-s004-rollback:5b4a848a-90b8-432e-9016-d931607218cd:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''1000 - 1500 AD'' restored on Pillkukayna', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5b4a848a-90b8-432e-9016-d931607218cd'::uuid, 'period_start', NULL, '1400', 'fields-wd1-2026-09-26b-s004-rollback:5b4a848a-90b8-432e-9016-d931607218cd:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''1400'' restored on Pillkukayna', '[{"source": "WD1 decision (counted, round 1, wd1-r1-b0003)", "decision": "clear", "status": "MISSING", "reasoning": "Pillkukayna (Isla del Sol, Lake Titicaca, Bolivia) is an Inca building attributed to the emperor Tupac Yupanqui; only the Spanish Wikipedia article turns that attribution into dates (his reign 1471-1493), while Lonely Planet and the other readable guides name the builder without any date and no second independent readable source dates the start, so it is cleared.", "value_page": null}]'::jsonb),
    ('5b4a848a-90b8-432e-9016-d931607218cd'::uuid, 'site_type', 'Palace', 'City/town/settlement', 'fields-wd1-2026-09-26b-s004-rollback:5b4a848a-90b8-432e-9016-d931607218cd:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''City/town/settlement'' restored on Pillkukayna', '[{"source": "https://tripomatic.com/en/destinations/copacabana-municipality/editors-choice", "url": "https://tripomatic.com/en/destinations/copacabana-municipality/editors-choice", "quote": "Two-story Inca palace on the southern tip of Isla del Sol.", "outcome": "found"}, {"source": "https://www.lonelyplanet.com/points-of-interest/pilko-kaina/468320", "url": "https://www.lonelyplanet.com/points-of-interest/pilko-kaina/468320", "quote": "The best-known site is the two-level Palacio del Inca, thought to have been constructed by the Incan emperor, Túpac Inca Yupanqui.", "outcome": "found"}, {"source": "https://correodelsur.com/cultura/20230618/con-un-atuendo-de-inca-choquehuanca-reinaugura-historico-palacio-de-pilkokaina-en-la-isla-del-sol.html", "url": "https://correodelsur.com/cultura/20230618/con-un-atuendo-de-inca-choquehuanca-reinaugura-historico-palacio-de-pilkokaina-en-la-isla-del-sol.html", "quote": "El vicepresidente David Choquehuanca reinauguró este domingo el histórico Palacio Pilkokaina", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0003)", "decision": "replace", "status": "MISSING", "reasoning": "A travel-guide database, Lonely Planet and the Bolivian press all describe Pilko Kaina / Pilkokaina on the south of Isla del Sol as an Inca palace (the two-storey Palacio del Inca), not a city or settlement, so the stored City/town/settlement is replaced by Palace.", "value_page": null}]'::jsonb),
    ('5b74783d-882a-4cc7-a2df-857b5a00c454'::uuid, 'source_url', 'https://lugares.inah.gob.mx/es/node/4487', 'https://www.lonelyplanet.com/mexico/oaxaca-state/bahias-de-huatulco/attractions/parque-eco-arqueologico-copalita/a/poi-sig/1079143/361606', 'fields-wd1-2026-09-26b-s004-rollback:5b74783d-882a-4cc7-a2df-857b5a00c454:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://www.lonelyplanet.com/mexico/oaxaca-state/bahias-de-huatulco/attractions/parque-eco-arqueologico-copalita/a/poi-sig/1079143/361606'' restored on Copalita Eco-Archaeological Park', '[{"source": "https://lugares.inah.gob.mx/es/node/4487", "url": "https://lugares.inah.gob.mx/es/node/4487", "quote": "Muy cerca de Bahías de Huatulco, este sitio fue un centro ceremonial. Está ubicado sobre unas lomas próximas a los acantilados de la costa oaxaqueña, dentro del Parque Ecoarqueológico Copalita", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Huatulco", "url": "https://en.wikipedia.org/wiki/Huatulco", "quote": "The Bocana del Río Copalita is a 2,500-year-old archaeological site located about ten kilometers from the bays, which is open to the public.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0095)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Lonely Planet link is a travel listing that redirects. INAH''s official page for the Bocana del Río Copalita archaeological zone, which lies inside the Parque Eco-Arqueológico Copalita, is the heritage agency''s entry for this very site and loads as plain HTML.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('5b9668cf-d08f-4877-ab48-c4f3b47f5117'::uuid, 'geom', 'SRID=4326;POINT(15.84247 43.92584)', '0101000020E61000000A9E17733EB32F4007C655E459F54540', 'fields-wd1-2026-09-26b-s004-rollback:5b9668cf-d08f-4877-ab48-c4f3b47f5117:geom', 'rollback of fields-wd1-2026-09-26b-s004: geom ''0101000020E61000000A9E17733EB32F4007C655E459F54540'' restored on Bribir, Šibenik-Knin County', '[{"source": "https://imperium.ahlfeldt.se/places/13906.html", "url": "https://imperium.ahlfeldt.se/places/13906.html", "quote": "43.92584, 15.84247", "outcome": "found"}, {"source": "https://www.wikidata.org/wiki/Q12749569", "url": "https://www.wikidata.org/wiki/Q12749569", "quote": "43°55''31.174\"N, 15°50''34.289\"E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0017)", "decision": "replace", "status": "CONFLICT", "reasoning": "The ancient site of Bribir is the hilltop Bribirska glavica (Roman Varvaria), which the Digital Atlas of the Roman Empire (Varvaria, Bribir) and the Wikidata item of Varvaria (archaeological site) both place at about 43.9255, 15.8427; the stored point is the enwiki point of the modern village at the foot of the hill, about 1.1 km south-east of the site.", "value_page": null}]'::jsonb),
    ('5b9668cf-d08f-4877-ab48-c4f3b47f5117'::uuid, 'lat', '43.92584', '43.91680578411256', 'fields-wd1-2026-09-26b-s004-rollback:5b9668cf-d08f-4877-ab48-c4f3b47f5117:lat', 'rollback of fields-wd1-2026-09-26b-s004: lat ''43.91680578411256'' restored on Bribir, Šibenik-Knin County', '[{"source": "https://imperium.ahlfeldt.se/places/13906.html", "url": "https://imperium.ahlfeldt.se/places/13906.html", "quote": "43.92584, 15.84247", "outcome": "found"}, {"source": "https://www.wikidata.org/wiki/Q12749569", "url": "https://www.wikidata.org/wiki/Q12749569", "quote": "43°55''31.174\"N, 15°50''34.289\"E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0017)", "decision": "replace", "status": "CONFLICT", "reasoning": "The ancient site of Bribir is the hilltop Bribirska glavica (Roman Varvaria), which the Digital Atlas of the Roman Empire (Varvaria, Bribir) and the Wikidata item of Varvaria (archaeological site) both place at about 43.9255, 15.8427; the stored point is the enwiki point of the modern village at the foot of the hill, about 1.1 km south-east of the site.", "value_page": null}]'::jsonb),
    ('5b9668cf-d08f-4877-ab48-c4f3b47f5117'::uuid, 'lon', '15.84247', '15.850085827477432', 'fields-wd1-2026-09-26b-s004-rollback:5b9668cf-d08f-4877-ab48-c4f3b47f5117:lon', 'rollback of fields-wd1-2026-09-26b-s004: lon ''15.850085827477432'' restored on Bribir, Šibenik-Knin County', '[{"source": "https://imperium.ahlfeldt.se/places/13906.html", "url": "https://imperium.ahlfeldt.se/places/13906.html", "quote": "43.92584, 15.84247", "outcome": "found"}, {"source": "https://www.wikidata.org/wiki/Q12749569", "url": "https://www.wikidata.org/wiki/Q12749569", "quote": "43°55''31.174\"N, 15°50''34.289\"E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0017)", "decision": "replace", "status": "CONFLICT", "reasoning": "The ancient site of Bribir is the hilltop Bribirska glavica (Roman Varvaria), which the Digital Atlas of the Roman Empire (Varvaria, Bribir) and the Wikidata item of Varvaria (archaeological site) both place at about 43.9255, 15.8427; the stored point is the enwiki point of the modern village at the foot of the hill, about 1.1 km south-east of the site.", "value_page": null}]'::jsonb),
    ('5b9668cf-d08f-4877-ab48-c4f3b47f5117'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s004-rollback:5b9668cf-d08f-4877-ab48-c4f3b47f5117:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''1 - 500 AD'' restored on Bribir, Šibenik-Knin County', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5b9668cf-d08f-4877-ab48-c4f3b47f5117'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s004-rollback:5b9668cf-d08f-4877-ab48-c4f3b47f5117:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''1'' restored on Bribir, Šibenik-Knin County', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0017)", "decision": "clear", "status": "MISSING", "reasoning": "The sources date the first occupation of Bribirska glavica only by period (Hrvatska enciklopedija: settled from the Eneolithic and Early Bronze Age; the Varvaria-Breberium-Bribir project: settled only from the Bronze Age), with no year, century or millennium; the stored 1 AD (the Roman municipium) is not the start, so the field is emptied.", "value_page": null}]'::jsonb),
    ('5be3cff9-8b07-4cfc-b667-933e2d0ae302'::uuid, 'period_name', '500 - 1000 AD', '1 - 500 AD', 'fields-wd1-2026-09-26b-s004-rollback:5be3cff9-8b07-4cfc-b667-933e2d0ae302:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''1 - 500 AD'' restored on Undavalli Caves', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(601) = ''500 - 1000 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5be3cff9-8b07-4cfc-b667-933e2d0ae302'::uuid, 'period_start', '601', '1', 'fields-wd1-2026-09-26b-s004-rollback:5be3cff9-8b07-4cfc-b667-933e2d0ae302:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''1'' restored on Undavalli Caves', '[{"source": "https://asiamaravaticircle.com/undavalli/history.html", "url": "https://asiamaravaticircle.com/undavalli/history.html", "quote": "Based on stylistic analysis, the earliest phase dates to the early to mid-7th century CE.", "outcome": "found"}, {"source": "https://www.incredibleindia.gov.in/en/andhra-pradesh/guntur/undavalli-caves", "url": "https://www.incredibleindia.gov.in/en/andhra-pradesh/guntur/undavalli-caves", "quote": "Undavalli Caves stand as an impressive testament to India''s vast rock-cut architecture heritage, dating back to the 7th century and bearing signs of Vishnu Kundina Dynasty''s influence", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0078)", "decision": "replace", "status": "MISSING", "reasoning": "The Archaeological Survey of India''s Amaravati Circle, the site''s custodian (citing Soundara Rajan), dates the earliest phase of the Undavalli excavation to the early to mid-7th century CE, and India''s Ministry of Tourism (Incredible India) likewise dates the caves to the 7th century under the Vishnukundinas; the popular 4th-5th century Buddhist-vihara origin repeated by Wikipedia is not the custodian''s dating, so the start moves to 601, in the 500-1000 AD bucket.", "value_page": null}]'::jsonb),
    ('5be3cff9-8b07-4cfc-b667-933e2d0ae302'::uuid, 'site_type', 'Cave Structures', 'Temple complex', 'fields-wd1-2026-09-26b-s004-rollback:5be3cff9-8b07-4cfc-b667-933e2d0ae302:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Temple complex'' restored on Undavalli Caves', '[{"source": "https://www.incredibleindia.gov.in/en/andhra-pradesh/guntur/undavalli-caves", "url": "https://www.incredibleindia.gov.in/en/andhra-pradesh/guntur/undavalli-caves", "quote": "Undavalli Caves stand as an impressive testament to India''s vast rock-cut architecture heritage", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Undavalli_Caves", "url": "https://en.wikipedia.org/wiki/Undavalli_Caves", "quote": "There are several caves and the best known largest one has three stories with a huge recreated statue of Vishnu in a reclining posture", "outcome": "found"}, {"source": "https://asiamaravaticircle.com/undavalli/history.html", "url": "https://asiamaravaticircle.com/undavalli/history.html", "quote": "The excavation is a multi-storeyed structure, nearly 28 meters in length and 15 meters in height, oriented east-west and facing north toward the river.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0078)", "decision": "replace", "status": "CONFLICT", "reasoning": "Incredible India, Wikipedia and the ASI describe Undavalli as a group of rock-cut caves hewn into a sandstone hill, the largest a multi-storeyed excavated cave temple, which the canonical type Cave Structures names; Temple complex misdescribes a set of rock-cut caves.", "value_page": null}]'::jsonb),
    ('5c40d704-05a0-4951-a5cf-20066d444d81'::uuid, 'period_name', NULL, '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s004-rollback:5c40d704-05a0-4951-a5cf-20066d444d81:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''4500 - 3000 BC'' restored on Walton Common', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5c40d704-05a0-4951-a5cf-20066d444d81'::uuid, 'period_start', NULL, '-4500', 'fields-wd1-2026-09-26b-s004-rollback:5c40d704-05a0-4951-a5cf-20066d444d81:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-4500'' restored on Walton Common', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0047)", "decision": "clear", "status": "MISSING", "reasoning": "The earliest remains are the Bronze Age saucer barrows and the banjo enclosure is dated only to the middle to late Iron Age; no source found gives a year, century or millennium for the start, so the stored -4500 is cleared.", "value_page": null}]'::jsonb),
    ('5c40d704-05a0-4951-a5cf-20066d444d81'::uuid, 'site_type', 'Earthwork', 'Barrow', 'fields-wd1-2026-09-26b-s004-rollback:5c40d704-05a0-4951-a5cf-20066d444d81:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Barrow'' restored on Walton Common', '[{"source": "https://www.megalithic.co.uk/article.php?sid=31849", "url": "https://www.megalithic.co.uk/article.php?sid=31849", "quote": "Type: Misc. Earthwork", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Walton_Common_banjo_enclosure", "url": "https://en.wikipedia.org/wiki/Walton_Common_banjo_enclosure", "quote": "The earthwork banks and ditch were detected from aerial photographs from 1930 and 1946.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0047)", "decision": "replace", "status": "CONFLICT", "reasoning": "The archaeology of Walton Common is a complex of prehistoric earthworks - a late Iron Age banjo enclosure with avenues, a field system and one or two Bronze Age saucer barrows; the Megalithic Portal types the principal monument as an earthwork and Wikipedia describes its earthwork banks, so Earthwork fits better than Barrow, which names only a minor part.", "value_page": null}]'::jsonb),
    ('5cd47e05-c322-4510-b40f-c1f75072c147'::uuid, 'geom', 'SRID=4326;POINT(45.99611 30.81583)', '0101000020E61000003BCDBFA05BFE464016479495ACCE3E40', 'fields-wd1-2026-09-26b-s004-rollback:5cd47e05-c322-4510-b40f-c1f75072c147:geom', 'rollback of fields-wd1-2026-09-26b-s004: geom ''0101000020E61000003BCDBFA05BFE464016479495ACCE3E40'' restored on Eridu', '[{"source": "https://en.wikipedia.org/wiki/Eridu", "url": "https://en.wikipedia.org/wiki/Eridu", "quote": "30.81583°N 45.99611°E", "outcome": "found"}, {"source": "https://archaeolist.com/sites/iraq/eridu", "url": "https://archaeolist.com/sites/iraq/eridu", "quote": "30.8158° N, 45.9961° E", "outcome": "found"}, {"source": "WD1 decision (counted, round 2, wd1-r2-b0002)", "decision": "replace", "status": "CONFLICT", "reasoning": "Eridu is Tell Abu Shahrain, whose main mound with the ziggurat is the site''s principal monument. English Wikipedia and Archaeolist both place it at 30.8158, 45.9961, about 1.3 km north-east of the stored point (30.8073, 45.9872), which lies in open desert away from the mound. The excavation literature agrees with the mound point (Strasbourg/Sapienza mission: main mound at 30 deg 49''01.62 N, 45 deg 59''46.57 E; Abu Tbeirah project: 30 deg 48''57.02 N, 45 deg 59''45.85 E; Vici.org: 30.81584, 45.996071), so the point is replaced.", "value_page": null}]'::jsonb),
    ('5cd47e05-c322-4510-b40f-c1f75072c147'::uuid, 'lat', '30.81583', '30.80732092733441', 'fields-wd1-2026-09-26b-s004-rollback:5cd47e05-c322-4510-b40f-c1f75072c147:lat', 'rollback of fields-wd1-2026-09-26b-s004: lat ''30.80732092733441'' restored on Eridu', '[{"source": "https://en.wikipedia.org/wiki/Eridu", "url": "https://en.wikipedia.org/wiki/Eridu", "quote": "30.81583°N 45.99611°E", "outcome": "found"}, {"source": "https://archaeolist.com/sites/iraq/eridu", "url": "https://archaeolist.com/sites/iraq/eridu", "quote": "30.8158° N, 45.9961° E", "outcome": "found"}, {"source": "WD1 decision (counted, round 2, wd1-r2-b0002)", "decision": "replace", "status": "CONFLICT", "reasoning": "Eridu is Tell Abu Shahrain, whose main mound with the ziggurat is the site''s principal monument. English Wikipedia and Archaeolist both place it at 30.8158, 45.9961, about 1.3 km north-east of the stored point (30.8073, 45.9872), which lies in open desert away from the mound. The excavation literature agrees with the mound point (Strasbourg/Sapienza mission: main mound at 30 deg 49''01.62 N, 45 deg 59''46.57 E; Abu Tbeirah project: 30 deg 48''57.02 N, 45 deg 59''45.85 E; Vici.org: 30.81584, 45.996071), so the point is replaced.", "value_page": null}]'::jsonb),
    ('5cd47e05-c322-4510-b40f-c1f75072c147'::uuid, 'lon', '45.99611', '45.98717126241032', 'fields-wd1-2026-09-26b-s004-rollback:5cd47e05-c322-4510-b40f-c1f75072c147:lon', 'rollback of fields-wd1-2026-09-26b-s004: lon ''45.98717126241032'' restored on Eridu', '[{"source": "https://en.wikipedia.org/wiki/Eridu", "url": "https://en.wikipedia.org/wiki/Eridu", "quote": "30.81583°N 45.99611°E", "outcome": "found"}, {"source": "https://archaeolist.com/sites/iraq/eridu", "url": "https://archaeolist.com/sites/iraq/eridu", "quote": "30.8158° N, 45.9961° E", "outcome": "found"}, {"source": "WD1 decision (counted, round 2, wd1-r2-b0002)", "decision": "replace", "status": "CONFLICT", "reasoning": "Eridu is Tell Abu Shahrain, whose main mound with the ziggurat is the site''s principal monument. English Wikipedia and Archaeolist both place it at 30.8158, 45.9961, about 1.3 km north-east of the stored point (30.8073, 45.9872), which lies in open desert away from the mound. The excavation literature agrees with the mound point (Strasbourg/Sapienza mission: main mound at 30 deg 49''01.62 N, 45 deg 59''46.57 E; Abu Tbeirah project: 30 deg 48''57.02 N, 45 deg 59''45.85 E; Vici.org: 30.81584, 45.996071), so the point is replaced.", "value_page": null}]'::jsonb),
    ('5d3974ac-5df3-4f32-9d62-634921bdaf5d'::uuid, 'source_url', 'https://www.exmoorher.co.uk/Monument/MEM22803', 'https://en.wikipedia.org/wiki/Dunkery_Hill', 'fields-wd1-2026-09-26b-s004-rollback:5d3974ac-5df3-4f32-9d62-634921bdaf5d:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/Dunkery_Hill'' restored on Dunkery Beacon - Dunkery Hill', '[{"source": "https://www.exmoorher.co.uk/Monument/MEM22803", "url": "https://www.exmoorher.co.uk/Monument/MEM22803", "quote": "Dunkery Beacon is a cairn, listed by Grinsell as Cutcombe 5.", "outcome": "found"}, {"source": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA155845", "url": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA155845", "quote": "Dunkery Beacon (Cutcombe 5), Dunkery Hill, Holnicote Estate", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0033)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the hill as a summit, and the site has no article of its own. The Exmoor National Park HER record MEM22803 ''Dunkery Beacon'' is the heritage register entry for the summit cairn (Cutcombe 5), and the National Trust''s record names the same monument.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('5d3ec998-b314-4e52-bf91-3f2a90f8afaf'::uuid, 'period_name', NULL, '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s004-rollback:5d3ec998-b314-4e52-bf91-3f2a90f8afaf:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''4500 - 3000 BC'' restored on Rough Tor', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5d3ec998-b314-4e52-bf91-3f2a90f8afaf'::uuid, 'period_start', NULL, '-4000', 'fields-wd1-2026-09-26b-s004-rollback:5d3ec998-b314-4e52-bf91-3f2a90f8afaf:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-4000'' restored on Rough Tor', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0044)", "decision": "clear", "status": "MISSING", "reasoning": "The enclosure is unexcavated: the National Trust record calls it ''probably of Neolithic or Bronze Age date'' and says only excavation can establish its date, and Wikipedia lists Rough Tor only as a possible tor enclosure; only Britain Express gives a probable early Neolithic range, so no two sources securely date the start and the stored -4000 is emptied.", "value_page": null}]'::jsonb),
    ('5d3ec998-b314-4e52-bf91-3f2a90f8afaf'::uuid, 'site_type', 'Settlement', 'Earthwork', 'fields-wd1-2026-09-26b-s004-rollback:5d3ec998-b314-4e52-bf91-3f2a90f8afaf:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Earthwork'' restored on Rough Tor', '[{"source": "https://www.megalithic.co.uk/article.php?sid=24050", "url": "https://www.megalithic.co.uk/article.php?sid=24050", "quote": "Neolithic - Bronze Age enclosed settlement. A small fortification on the summit of Rough Tor built between and including two rock outcrops.", "outcome": "found"}, {"source": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA102280", "url": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA102280", "quote": "ENCLOSED HUT CIRCLE SETTLEMENT (Prehistoric - 500000 BC to 42 AD)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0044)", "decision": "replace", "status": "CONFLICT", "reasoning": "The monument is a stone-walled hilltop enclosure containing over twenty house platforms; the Pastscape record quoted by the Megalithic Portal and the National Trust record both classify it as an enclosed settlement, not an earthwork, so the type is Settlement.", "value_page": null}]'::jsonb),
    ('5d5f1cc8-18af-42b2-860a-65862b328498'::uuid, 'site_type', 'Fort', 'City/town/settlement', 'fields-wd1-2026-09-26b-s004-rollback:5d5f1cc8-18af-42b2-860a-65862b328498:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''City/town/settlement'' restored on Bremetennacum', '[{"source": "https://en.wikipedia.org/wiki/Bremetennacum", "url": "https://en.wikipedia.org/wiki/Bremetennacum", "quote": "A fort remained at Ribchester until the 4th century AD and its remains can still be seen around the present village.", "outcome": "found"}, {"source": "https://www.roman-britain.co.uk/places/bremetenacum/", "url": "https://www.roman-britain.co.uk/places/bremetenacum/", "quote": "The fort was damaged around 196/7AD and the H.Q. building destroyed, but a Severan inscription records building restorations to both the fort and at least one temple erected outside the defences.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0028)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and roman-britain.co.uk both describe Bremetennacum at Ribchester as a Roman auxiliary fort (timber c. AD 72/3, rebuilt in stone); the vicus grew up around it, so the site is a fort, not a town.", "value_page": null}]'::jsonb),
    ('5d7bd109-0da2-4c89-b92e-aba77991d673'::uuid, 'site_type', 'Shipwreck', 'Museum', 'fields-wd1-2026-09-26b-s004-rollback:5d7bd109-0da2-4c89-b92e-aba77991d673:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Museum'' restored on The Ships of De Meern', '[{"source": "https://mass.cultureelerfgoed.nl/meern-1", "url": "https://mass.cultureelerfgoed.nl/meern-1", "quote": "Mr. H. Joosten, a member of a local historical society, found wood belonging to a shipwreck in a small hole that was being dug in 1997.", "outcome": "found"}, {"source": "https://vici.org/vici/13840/", "url": "https://vici.org/vici/13840/", "quote": "Class: Shipwreck", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/The_Ships_of_De_Meern", "url": "https://en.wikipedia.org/wiki/The_Ships_of_De_Meern", "quote": "The ship was presumably wrecked due to navigational error", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0100)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is the find site of Roman shipwrecks (De Meern 1 to 6), described as a shipwreck by the Cultural Heritage Agency''s MaSS, Vici.org and Wikipedia; ''Museum'' is the Hoge Woerd museum that now keeps De Meern 1, not the site.", "value_page": null}]'::jsonb),
    ('5d8a914c-d69d-409c-9713-588113811da5'::uuid, 'geom', 'SRID=4326;POINT(8.129 52.408)', '0101000020E6100000CC308299993920403C384E18E9324A40', 'fields-wd1-2026-09-26b-s004-rollback:5d8a914c-d69d-409c-9713-588113811da5:geom', 'rollback of fields-wd1-2026-09-26b-s004: geom ''0101000020E6100000CC308299993920403C384E18E9324A40'' restored on Kalkrieser Berg', '[{"source": "https://en.wikipedia.org/wiki/Battle_of_the_Teutoburg_Forest", "url": "https://en.wikipedia.org/wiki/Battle_of_the_Teutoburg_Forest", "quote": "52°24′29″N 8°07′44″E", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=46028", "url": "https://www.megalithic.co.uk/article.php?sid=46028", "quote": "Latitude: 52.407500N Longitude: 8.130000E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0058)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is the Kalkriese battlefield, whose core - the Oberesch find spot with the Germanic rampart, now the Museum and Park - lies at the foot of the hill; Wikipedia''s Battle of the Teutoburg Forest and the Megalithic Portal place it at about 52.408, 8.129. The stored point is the hill''s summit, about 1.7 km away, so it is replaced.", "value_page": null}]'::jsonb),
    ('5d8a914c-d69d-409c-9713-588113811da5'::uuid, 'lat', '52.408', '52.397738493149944', 'fields-wd1-2026-09-26b-s004-rollback:5d8a914c-d69d-409c-9713-588113811da5:lat', 'rollback of fields-wd1-2026-09-26b-s004: lat ''52.397738493149944'' restored on Kalkrieser Berg', '[{"source": "https://en.wikipedia.org/wiki/Battle_of_the_Teutoburg_Forest", "url": "https://en.wikipedia.org/wiki/Battle_of_the_Teutoburg_Forest", "quote": "52°24′29″N 8°07′44″E", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=46028", "url": "https://www.megalithic.co.uk/article.php?sid=46028", "quote": "Latitude: 52.407500N Longitude: 8.130000E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0058)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is the Kalkriese battlefield, whose core - the Oberesch find spot with the Germanic rampart, now the Museum and Park - lies at the foot of the hill; Wikipedia''s Battle of the Teutoburg Forest and the Megalithic Portal place it at about 52.408, 8.129. The stored point is the hill''s summit, about 1.7 km away, so it is replaced.", "value_page": null}]'::jsonb),
    ('5d8a914c-d69d-409c-9713-588113811da5'::uuid, 'lon', '8.129', '8.112499997274789', 'fields-wd1-2026-09-26b-s004-rollback:5d8a914c-d69d-409c-9713-588113811da5:lon', 'rollback of fields-wd1-2026-09-26b-s004: lon ''8.112499997274789'' restored on Kalkrieser Berg', '[{"source": "https://en.wikipedia.org/wiki/Battle_of_the_Teutoburg_Forest", "url": "https://en.wikipedia.org/wiki/Battle_of_the_Teutoburg_Forest", "quote": "52°24′29″N 8°07′44″E", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=46028", "url": "https://www.megalithic.co.uk/article.php?sid=46028", "quote": "Latitude: 52.407500N Longitude: 8.130000E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0058)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is the Kalkriese battlefield, whose core - the Oberesch find spot with the Germanic rampart, now the Museum and Park - lies at the foot of the hill; Wikipedia''s Battle of the Teutoburg Forest and the Megalithic Portal place it at about 52.408, 8.129. The stored point is the hill''s summit, about 1.7 km away, so it is replaced.", "value_page": null}]'::jsonb),
    ('5d8a914c-d69d-409c-9713-588113811da5'::uuid, 'site_type', 'Archaeological site', 'Museum', 'fields-wd1-2026-09-26b-s004-rollback:5d8a914c-d69d-409c-9713-588113811da5:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Museum'' restored on Kalkrieser Berg', '[{"source": "https://en.wikipedia.org/wiki/Battle_of_the_Teutoburg_Forest", "url": "https://en.wikipedia.org/wiki/Battle_of_the_Teutoburg_Forest", "quote": "The archeological site at Kalkriese hill", "outcome": "found"}, {"source": "https://www.niedersachsen-tourism.com/poi/varusschlacht-im-osnabruecker-land-museum-und-park-kalkriese", "url": "https://www.niedersachsen-tourism.com/poi/varusschlacht-im-osnabruecker-land-museum-und-park-kalkriese", "quote": "Today Kalkriese is the first ancient battlefield in Europe to be archaeologically investigated.", "outcome": "found"}, {"source": "https://www.kalkriese-varusschlacht.de/museum-park.html", "url": "https://www.kalkriese-varusschlacht.de/museum-park.html", "quote": "Kalkriese ist allerdings nicht nur ein spektakulärer Fundort, sondern zugleich ein Bodendenkmal, dessen Charakter und Ausdehnung Forschung und Denkmalpflege vor bisher ungekannte Herausforderungen stellt.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0058)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is an ancient battlefield known from its archaeological finds (a find spot and protected ground monument, Bodendenkmal); the museum is a modern institution on it, not the site''s type. No canonical type for a battlefield exists, so the generic Archaeological site is the most specific that holds.", "value_page": null}]'::jsonb),
    ('5d8a914c-d69d-409c-9713-588113811da5'::uuid, 'source_url', 'https://de.wikipedia.org/wiki/Fundregion_Kalkriese', 'https://en.wikipedia.org/wiki/Kalkrieser_Berg', 'fields-wd1-2026-09-26b-s004-rollback:5d8a914c-d69d-409c-9713-588113811da5:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/Kalkrieser_Berg'' restored on Kalkrieser Berg', '[{"source": "https://de.wikipedia.org/wiki/Fundregion_Kalkriese", "url": "https://de.wikipedia.org/wiki/Fundregion_Kalkriese", "quote": "Lage der Fundregion und des Museums; Kalkrieser Berg gelb, Wiehengebirge grün hervorgehoben.", "outcome": "found"}, {"source": "https://www.zeilenabstand.net/varusschlacht-kalkriese-vom-mythos-zum-museum/", "url": "https://www.zeilenabstand.net/varusschlacht-kalkriese-vom-mythos-zum-museum/", "quote": "Ort des Geschehens: der Kalkrieser Berg am Wiehengebirge", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0058)", "decision": "replace", "status": "CONFLICT", "reasoning": "The English article is about the hill itself; the site - the Roman find region and probable Varus battlefield at the Kalkrieser Berg - has its own article in German Wikipedia, Fundregion Kalkriese. An independent account of the Kalkriese battlefield names the Kalkrieser Berg as the place of the events.", "value_page": {"lang": "de", "problem": null, "resolved_title": "Fundregion Kalkriese", "unreadable": false, "wikibase_item": "Q106519739"}}]'::jsonb),
    ('5d8cbd90-1826-4ab0-b44f-94574d7dccc4'::uuid, 'site_type', 'Sanctuary', 'Megalithic structures', 'fields-wd1-2026-09-26b-s004-rollback:5d8cbd90-1826-4ab0-b44f-94574d7dccc4:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Megalithic structures'' restored on Fountain of the Idol', '[{"source": "https://arqueologia.patrimoniocultural.pt/index.php/?sid=visitaveis&subsid=53748&lang=en", "url": "https://arqueologia.patrimoniocultural.pt/index.php/?sid=visitaveis&subsid=53748&lang=en", "quote": "Despite the difference of interpretations, agreement is made regarding this space being a sanctuary dedicated to an aquatic divinity.", "outcome": "found"}, {"source": "https://vive.eixoatlantico.com/en/recurso/fonte-do-idolo-2/", "url": "https://vive.eixoatlantico.com/en/recurso/fonte-do-idolo-2/", "quote": "a rock-cut sanctuary from the beginning of the 1st century associated with the cult of water.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0118)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Fonte do Ídolo is a Roman rock-cut sanctuary with reliefs and inscriptions to water deities, not a megalithic structure; the heritage agency''s portal and the Eixo Atlántico heritage guide both call it a sanctuary.", "value_page": null}]'::jsonb),
    ('5e0211cd-62e0-47c8-95f5-3085dbd75768'::uuid, 'period_name', '500 BC - 1 AD', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s004-rollback:5e0211cd-62e0-47c8-95f5-3085dbd75768:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''1500 - 500 BC'' restored on Midhowe Broch', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-200) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5e0211cd-62e0-47c8-95f5-3085dbd75768'::uuid, 'period_start', '-200', '-1000', 'fields-wd1-2026-09-26b-s004-rollback:5e0211cd-62e0-47c8-95f5-3085dbd75768:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-1000'' restored on Midhowe Broch', '[{"source": "https://www.stonepages.com/ancient_scotland/sites/midhow_b.htm", "url": "https://www.stonepages.com/ancient_scotland/sites/midhow_b.htm", "quote": "Period : 2nd century BC", "outcome": "found"}, {"source": "https://rousayremembered.com/midhowe-broch-and-cairn/", "url": "https://rousayremembered.com/midhowe-broch-and-cairn/", "quote": "Constructed and used sometime between 200BC and 200AD", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0022)", "decision": "replace", "status": "MISSING", "reasoning": "Stone Pages dates Midhowe Broch to the 2nd century BC and Rousay Remembered says it was constructed and used sometime between 200BC and 200AD, so the start is c. 200 BC, in the 500 BC - 1 AD bucket, not the stored -1000.", "value_page": null}]'::jsonb),
    ('5e0211cd-62e0-47c8-95f5-3085dbd75768'::uuid, 'site_type', 'Fort', 'City/town/settlement', 'fields-wd1-2026-09-26b-s004-rollback:5e0211cd-62e0-47c8-95f5-3085dbd75768:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''City/town/settlement'' restored on Midhowe Broch', '[{"source": "https://www.historicenvironment.scot/visit/all/midhowe-broch/", "url": "https://www.historicenvironment.scot/visit/all/midhowe-broch/", "quote": "Visit a fortified Iron Age settlement dramatically positioned above the coast", "outcome": "found"}, {"source": "https://www.stonepages.com/ancient_scotland/sites/midhow_b.htm", "url": "https://www.stonepages.com/ancient_scotland/sites/midhow_b.htm", "quote": "This well preserved Iron Age broch was built on a promontory on the island of Rousay (Orkney), with its landward side massively defended by walls and ditches", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0022)", "decision": "replace", "status": "CONFLICT", "reasoning": "Historic Environment Scotland calls Midhowe a fortified Iron Age settlement and Stone Pages an Iron Age broch on a promontory defended by walls and ditches, so it is a fortified broch (Wikidata: broch and promontory fort), not a city, town or settlement in the urban sense; Fort is the most specific canonical type.", "value_page": null}]'::jsonb),
    ('5e0e44b0-b557-4ffe-9cc1-7db2d3e3ecfc'::uuid, 'site_type', 'Gate', 'Megalithic structures', 'fields-wd1-2026-09-26b-s004-rollback:5e0e44b0-b557-4ffe-9cc1-7db2d3e3ecfc:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Megalithic structures'' restored on First Pylon', '[{"source": "https://digitalkarnak.ucsc.edu/1st-pylon/", "url": "https://digitalkarnak.ucsc.edu/1st-pylon/", "quote": "Nectanebo built Pylon I, in concert with a new huge enclosure wall surrounding the Amun temple precinct, to serve as a new monumental entrance to the temple.", "outcome": "found"}, {"source": "https://digitalkarnak.ucsc.edu/1st-pylon/", "url": "https://digitalkarnak.ucsc.edu/1st-pylon/", "quote": "The huge entrance gate between the pylon towers was at some point fitted with a smaller, interior gate.", "outcome": "found"}, {"source": "https://madainproject.com/first_pylon_karnak_temple", "url": "https://madainproject.com/first_pylon_karnak_temple", "quote": "is the last to be built at Karnak and is the main entrance into the temple today.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0022)", "decision": "replace", "status": "CONFLICT", "reasoning": "The First Pylon is a pair of towers flanking the monumental entrance gate of the Amun temple at Karnak; Digital Karnak calls it a monumental entrance with a huge entrance gate and the Madain Project the main entrance into the temple. It is a temple gateway, not a megalithic structure, so Gate is the most specific type.", "value_page": null}]'::jsonb),
    ('5e0e44b0-b557-4ffe-9cc1-7db2d3e3ecfc'::uuid, 'source_url', 'https://digitalkarnak.ucsc.edu/1st-pylon/', 'https://en.wikipedia.org/wiki/Precinct_of_Amun-Re', 'fields-wd1-2026-09-26b-s004-rollback:5e0e44b0-b557-4ffe-9cc1-7db2d3e3ecfc:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/Precinct_of_Amun-Re'' restored on First Pylon', '[{"source": "https://digitalkarnak.ucsc.edu/1st-pylon/", "url": "https://digitalkarnak.ucsc.edu/1st-pylon/", "quote": "The first pylon stands at the far west of the Karnak precinct and is the main entrance to the temple today.", "outcome": "found"}, {"source": "https://madainproject.com/first_pylon_karnak_temple", "url": "https://madainproject.com/first_pylon_karnak_temple", "quote": "The first pylon, the facade of the Amun-Re precinct with avenue of the sphinxes leading up to the entrance.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0022)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is about the whole Precinct of Amun-Re, and the First Pylon has no Wikipedia article; UCSC''s Digital Karnak has a page on the 1st Pylon itself (its builder, measurements and construction phases), and the Madain Project describes the same pylon.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('5e1bd6c1-43bd-4a34-a7ae-7ea240f9f7b2'::uuid, 'period_name', NULL, '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s004-rollback:5e1bd6c1-43bd-4a34-a7ae-7ea240f9f7b2:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''500 BC - 1 AD'' restored on La Chapelle-aux-Saints', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5e1bd6c1-43bd-4a34-a7ae-7ea240f9f7b2'::uuid, 'period_start', NULL, '-500', 'fields-wd1-2026-09-26b-s004-rollback:5e1bd6c1-43bd-4a34-a7ae-7ea240f9f7b2:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-500'' restored on La Chapelle-aux-Saints', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0053)", "decision": "clear", "status": "MISSING", "reasoning": "The sources give the Mousterian deposits and the burial only as ''years old'' or as the Middle Palaeolithic, never as a BC year, century or millennium. The stored -500 is plainly wrong, and no quotable start remains.", "value_page": null}]'::jsonb),
    ('5e1bd6c1-43bd-4a34-a7ae-7ea240f9f7b2'::uuid, 'site_type', 'Cave', 'Cave Structures', 'fields-wd1-2026-09-26b-s004-rollback:5e1bd6c1-43bd-4a34-a7ae-7ea240f9f7b2:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Cave Structures'' restored on La Chapelle-aux-Saints', '[{"source": "https://en.wikipedia.org/wiki/La_Chapelle-aux-Saints", "url": "https://en.wikipedia.org/wiki/La_Chapelle-aux-Saints", "quote": "The La Chapelle-aux-Saints cave, bordering the Sourdoire valley, revealed many archeological artifacts belonging to the late Mousterian techno-complex,", "outcome": "found"}, {"source": "https://journals.openedition.org/adlfi/80228", "url": "https://journals.openedition.org/adlfi/80228", "quote": "La Bouffia Bonneval à La Chapelle-aux-Saints est une petite cavité du Sud-Corrèze, creusée à l’interface des marnes et des cargneules de l’Hettangien.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0053)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the ADLFI excavation notice both describe the site as a small natural cave (cavité) holding Middle Palaeolithic deposits. Cave fits better than Cave Structures, since no built structures are described.", "value_page": null}]'::jsonb),
    ('5e1bd6c1-43bd-4a34-a7ae-7ea240f9f7b2'::uuid, 'source_url', 'https://it.wikipedia.org/wiki/Sito_archeologico_di_La_Chapelle-aux-Saints', 'https://en.wikipedia.org/wiki/La_Chapelle-aux-Saints', 'fields-wd1-2026-09-26b-s004-rollback:5e1bd6c1-43bd-4a34-a7ae-7ea240f9f7b2:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/La_Chapelle-aux-Saints'' restored on La Chapelle-aux-Saints', '[{"source": "https://it.wikipedia.org/wiki/Sito_archeologico_di_La_Chapelle-aux-Saints", "url": "https://it.wikipedia.org/wiki/Sito_archeologico_di_La_Chapelle-aux-Saints", "quote": "Il Sito archeologico di La Chapelle-aux-Saints è una grotta, chiamata Bouffia Bonneval", "outcome": "found"}, {"source": "https://journals.openedition.org/adlfi/80228", "url": "https://journals.openedition.org/adlfi/80228", "quote": "La Bouffia Bonneval à La Chapelle-aux-Saints est une petite cavité du Sud-Corrèze", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0053)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored page is about the commune. The Italian Wikipedia article is the only Wikipedia article about the archaeological site itself, the Bouffia Bonneval cave (it is the sitelink of the cave''s Wikidata item), and the ADLFI notice names the same cave.", "value_page": {"lang": "it", "problem": null, "resolved_title": "Sito archeologico di La Chapelle-aux-Saints", "unreadable": false, "wikibase_item": "Q22950972"}}]'::jsonb),
    ('5e53212a-df01-4e4e-b9d0-fde511c2ec55'::uuid, 'period_name', NULL, '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s004-rollback:5e53212a-df01-4e4e-b9d0-fde511c2ec55:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''4500 - 3000 BC'' restored on Gilwern Hill, Powys', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5e53212a-df01-4e4e-b9d0-fde511c2ec55'::uuid, 'period_start', NULL, '-4000', 'fields-wd1-2026-09-26b-s004-rollback:5e53212a-df01-4e4e-b9d0-fde511c2ec55:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-4000'' restored on Gilwern Hill, Powys', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0154)", "decision": "clear", "status": "MISSING", "reasoning": "Only Cadw dates the Gilwern Hill stone row (''probably dating to the Bronze Age (c.2300 BC - 800 BC)'', which is the 3000 - 1500 BC bucket, not the stored 4500 - 3000 BC); Coflein and the Megalithic Portal give only ''Prehistoric'' or ''Neolithic and Bronze Age'' and the Heneb HER text repeats Cadw, so no two independent sources date the start.", "value_page": null}]'::jsonb),
    ('5e53212a-df01-4e4e-b9d0-fde511c2ec55'::uuid, 'source_url', 'https://coflein.gov.uk/en/sites/403125', 'https://en.wikipedia.org/wiki/Gilwern_Hill,_Powys', 'fields-wd1-2026-09-26b-s004-rollback:5e53212a-df01-4e4e-b9d0-fde511c2ec55:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/Gilwern_Hill,_Powys'' restored on Gilwern Hill, Powys', '[{"source": "https://coflein.gov.uk/en/sites/403125", "url": "https://coflein.gov.uk/en/sites/403125", "quote": "The remains of the Court Stone Row are situated on a summit of a large rounded eminence in a natural amphitheatre on the south-west facing slopes of Gilwern hill.", "outcome": "found"}, {"source": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=4130", "url": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=4130", "quote": "Reference Number RD224 Name Court stone row", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Gilwern_Hill,_Powys", "url": "https://en.wikipedia.org/wiki/Gilwern_Hill,_Powys", "quote": "Gilwern Hill, Powys", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0154)", "decision": "replace", "status": "CONFLICT", "reasoning": "The English Wikipedia article is about the hill (geology, fossils) and has one sentence on two prehistoric stone rows at its southern end; the Coflein record NPRN 403125 for the Court Stone Row on Gilwern hill is a register entry about the megalithic stones themselves, and Cadw''s scheduled monument RD224 independently names the same Court stone row on Gilwern hill.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('5e55b918-e5c7-4224-aa90-f244416f696f'::uuid, 'period_name', '500 BC - 1 AD', '1 - 500 AD', 'fields-wd1-2026-09-26b-s004-rollback:5e55b918-e5c7-4224-aa90-f244416f696f:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''1 - 500 AD'' restored on Pyramid of Hellenikon', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-400) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5e55b918-e5c7-4224-aa90-f244416f696f'::uuid, 'period_start', '-400', '1', 'fields-wd1-2026-09-26b-s004-rollback:5e55b918-e5c7-4224-aa90-f244416f696f:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''1'' restored on Pyramid of Hellenikon', '[{"source": "http://odysseus.culture.gr/h/2/eh251.jsp?obj_id=1805", "url": "http://odysseus.culture.gr/h/2/eh251.jsp?obj_id=1805", "quote": "According to evidence from the excavations and the typical features of the structure which dates to the end of the 4th century B.C. and not to the prehistoric period, as some scientists have been recently willing to demonstrate.", "outcome": "found"}, {"source": "https://visitpeloponnese.com/en/prdct/pyramid-elliniko", "url": "https://visitpeloponnese.com/en/prdct/pyramid-elliniko", "quote": "It is now fairly widely accepted that it was built at the end of the 4th century BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0071)", "decision": "replace", "status": "MISSING", "reasoning": "The Greek Ministry of Culture and the Region of Peloponnese tourism site both date the construction of the Hellinikon pyramid to the end of the 4th century BC (the Early Bronze Age thermoluminescence dating is rejected by both); the stored 1 AD bucket is wrong, so the start becomes the 4th century BC, -400.", "value_page": null}]'::jsonb),
    ('5e55b918-e5c7-4224-aa90-f244416f696f'::uuid, 'site_type', 'Fort', 'Megalithic stones', 'fields-wd1-2026-09-26b-s004-rollback:5e55b918-e5c7-4224-aa90-f244416f696f:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Megalithic stones'' restored on Pyramid of Hellenikon', '[{"source": "http://odysseus.culture.gr/h/2/eh251.jsp?obj_id=1805", "url": "http://odysseus.culture.gr/h/2/eh251.jsp?obj_id=1805", "quote": "there is a small fort at present known as the ''pyramid'' of Hellenikon.", "outcome": "found"}, {"source": "http://odysseus.culture.gr/h/2/eh251.jsp?obj_id=1805", "url": "http://odysseus.culture.gr/h/2/eh251.jsp?obj_id=1805", "quote": "while nowadays there is no doubt that it was a fort of the type of small strong-holds which controlled the arterial roads and which are known from other regions of the Argolid.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Greek_pyramids", "url": "https://en.wikipedia.org/wiki/Greek_pyramids", "quote": "L. Lord who concluded that both the structure at Ligurio and the one at Cephalaria were \"guard houses capable of accommodating a small garrison who could control the countryside and be safe behind their walls from surprise attacks by a few persons\".", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0071)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Ministry of Culture describes the ''pyramid'' as a small fort controlling the Argos-Tegea road, and Wikipedia reports the excavator Lord''s conclusion that the Kefalari (Hellinikon) structure was a garrisoned guard house; it is a small fortified post, not megalithic stones.", "value_page": null}]'::jsonb),
    ('5e710f8a-fc74-40b6-ab42-424a3ded4713'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s004-rollback:5e710f8a-fc74-40b6-ab42-424a3ded4713:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''1500 - 500 BC'' restored on Hamble Common Camp', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5e710f8a-fc74-40b6-ab42-424a3ded4713'::uuid, 'period_start', NULL, '-1000', 'fields-wd1-2026-09-26b-s004-rollback:5e710f8a-fc74-40b6-ab42-424a3ded4713:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-1000'' restored on Hamble Common Camp', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0035)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia, Eastleigh Borough Council''s history page and the Hamble Conservation Volunteers only call the bank and ditch Iron Age, with no year, century or millennium; no two sources date its construction, so the stored -1000 cannot be confirmed.", "value_page": null}]'::jsonb),
    ('5e710f8a-fc74-40b6-ab42-424a3ded4713'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s004-rollback:5e710f8a-fc74-40b6-ab42-424a3ded4713:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Fortress/citadel'' restored on Hamble Common Camp', '[{"source": "https://en.wikipedia.org/wiki/Hamble_Common", "url": "https://en.wikipedia.org/wiki/Hamble_Common", "quote": "This is believed to be an Iron Age settlement, with the ditch being a defensive structure. The ''wet nature'' of the area has ensured that most of these structures have remained intact. Some have suggested this site could have been a promontory fort.", "outcome": "found"}, {"source": "https://ukhillfortlidar.myportfolio.com/hamble-common", "url": "https://ukhillfortlidar.myportfolio.com/hamble-common", "quote": "Just south of Southampton at the end of the peninsula called Hamble Point is the contested degraded hillfort, Hamble Common. Two main defensive banks separate Hamble Point with the mainland.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0035)", "decision": "replace", "status": "CONFLICT", "reasoning": "The camp is an Iron Age defensive bank and ditch cutting off the Hamble Point promontory; Wikipedia describes it as a possible promontory fort and the UK hillfort LiDAR survey as a (contested) hillfort, so ''Fort'' fits better than ''Fortress/citadel'', which no source uses.", "value_page": null}]'::jsonb),
    ('5e710f8a-fc74-40b6-ab42-424a3ded4713'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Hamble_Common', 'https://en.wikipedia.org/wiki/Hamble_Common_Camp', 'fields-wd1-2026-09-26b-s004-rollback:5e710f8a-fc74-40b6-ab42-424a3ded4713:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/Hamble_Common_Camp'' restored on Hamble Common Camp', '[{"source": "https://en.wikipedia.org/wiki/Hamble_Common", "url": "https://en.wikipedia.org/wiki/Hamble_Common", "quote": "The site is now referred to as Hamble Common Camp.", "outcome": "found"}, {"source": "https://ukhillfortlidar.myportfolio.com/hamble-common", "url": "https://ukhillfortlidar.myportfolio.com/hamble-common", "quote": "Just south of Southampton at the end of the peninsula called Hamble Point is the contested degraded hillfort, Hamble Common.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0035)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is a redirect into a section; the camp has no article of its own, and Wikipedia treats it in the Hamble Common article, whose scheduled-monument entry is the promontory earthwork and which names the site Hamble Common Camp; the LiDAR hillfort survey names the same site.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Hamble Common", "unreadable": false, "wikibase_item": "Q127282236"}}]'::jsonb),
    ('5e7bedef-ef5e-44b4-b479-ec462b3ba954'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s004-rollback:5e7bedef-ef5e-44b4-b479-ec462b3ba954:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''1 - 500 AD'' restored on Black Mountain (Pima County, Arizona)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5e7bedef-ef5e-44b4-b479-ec462b3ba954'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s004-rollback:5e7bedef-ef5e-44b4-b479-ec462b3ba954:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''1'' restored on Black Mountain (Pima County, Arizona)', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0148)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia only says the mountain top carries the ruins of an ancient Hohokam fortification, with no date. The dating evidence (Tanque Verde red-on-brown pottery, early Classic period) sits in Fontana, Greenleaf and Cassidy 1959 (The Kiva) and later trincheras studies on JSTOR, tDAR and ResearchGate, all closed to a plain GET. No readable page dates the start, so the field is emptied.", "value_page": null}]'::jsonb),
    ('5e7bedef-ef5e-44b4-b479-ec462b3ba954'::uuid, 'site_type', 'Fortification', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s004-rollback:5e7bedef-ef5e-44b4-b479-ec462b3ba954:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Fortress/citadel'' restored on Black Mountain (Pima County, Arizona)', '[{"source": "https://en.wikipedia.org/wiki/Black_Mountain_(Pima_County,_Arizona)", "url": "https://en.wikipedia.org/wiki/Black_Mountain_(Pima_County,_Arizona)", "quote": "On top of Black Mountain are the ruins of an ancient Hohokam fortification.", "outcome": "found"}, {"source": "https://uamr.lib.arizona.edu/item/246028", "url": "https://uamr.lib.arizona.edu/item/246028", "quote": "A fortified Arizona mountain Author B. L. Fontana, J. C. Greanleaf, D. D. Cassidy Article Date December 1959 Article Abstract Black mountain southwest of Tucson", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0148)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia calls the site the ruins of an ancient Hohokam fortification, and the University of Arizona index entry for Fontana, Greenleaf and Cassidy (1959, The Kiva 25) is titled A fortified Arizona mountain and is about Black Mountain southwest of Tucson. Neither calls it a fortress or citadel; fortification is the word both use.", "value_page": null}]'::jsonb),
    ('5e7bfc36-038c-43e0-825c-c6b55f0dd78c'::uuid, 'period_name', NULL, '1000 - 1500 AD', 'fields-wd1-2026-09-26b-s004-rollback:5e7bfc36-038c-43e0-825c-c6b55f0dd78c:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''1000 - 1500 AD'' restored on Patallacta', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5e7bfc36-038c-43e0-825c-c6b55f0dd78c'::uuid, 'period_start', NULL, '1000', 'fields-wd1-2026-09-26b-s004-rollback:5e7bfc36-038c-43e0-825c-c6b55f0dd78c:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''1000'' restored on Patallacta', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0112)", "decision": "clear", "status": "MISSING", "reasoning": "The sources describe Patallacta as an Inca settlement burned in 1536, but none gives a year or century for its construction or first occupation (only tour pages that are unreadable or speak of the Inca empire in general), so no start date can be quoted from two sources and the field is emptied.", "value_page": null}]'::jsonb),
    ('5ea99baa-5ab5-4f9f-adb9-48bc53e97363'::uuid, 'period_name', NULL, '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s004-rollback:5ea99baa-5ab5-4f9f-adb9-48bc53e97363:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''3000 - 1500 BC'' restored on Lepsius No.25 Pyramid', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5ea99baa-5ab5-4f9f-adb9-48bc53e97363'::uuid, 'period_start', NULL, '-3000', 'fields-wd1-2026-09-26b-s004-rollback:5ea99baa-5ab5-4f9f-adb9-48bc53e97363:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-3000'' restored on Lepsius No.25 Pyramid', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0023)", "decision": "clear", "status": "MISSING", "reasoning": "Only English Wikipedia gives a year (infobox ''Constructed c. 2430 BC''); the excavators, the Czech Institute of Egyptology, date the double tomb Lepsius no. 25 only to the Fifth Dynasty, and no second independent page found (Magdolen''s typology paper, travel2egypt, egyptphoto) states a year, century or millennium for it, so the start cannot be sourced twice.", "value_page": null}]'::jsonb),
    ('5ea99baa-5ab5-4f9f-adb9-48bc53e97363'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Double_Pyramid', 'https://en.wikipedia.org/wiki/Lepsius_XXIV', 'fields-wd1-2026-09-26b-s004-rollback:5ea99baa-5ab5-4f9f-adb9-48bc53e97363:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/Lepsius_XXIV'' restored on Lepsius No.25 Pyramid', '[{"source": "https://en.wikipedia.org/wiki/Double_Pyramid", "url": "https://en.wikipedia.org/wiki/Double_Pyramid", "quote": "The Double Pyramid, also known as Lepsius XXV, designates a pair of adjacent monuments located on the south-eastern edge of the Abusir necropolis, south of the pyramid Lepsius XXIV and of the pyramid of Khentkaus II.", "outcome": "found"}, {"source": "https://cegu.ff.cuni.cz/en/research/projects/field-projects/abusir/list-of-structures-in-abusir/central-abusir-royal/", "url": "https://cegu.ff.cuni.cz/en/research/projects/field-projects/abusir/list-of-structures-in-abusir/central-abusir-royal/", "quote": "An extraordinary double tomb Lepsius no. 25, located to the south of AC 22.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0023)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the article on the neighbouring pyramid Lepsius XXIV (Q1820141); the site''s own English article, for item Q1377626, is ''Double Pyramid'' (Lepsius XXV redirects there), and the Czech Institute of Egyptology''s list of Abusir structures describes the same double tomb Lepsius no. 25.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Double Pyramid", "unreadable": false, "wikibase_item": "Q1377626"}}]'::jsonb),
    ('5f10ac9c-682b-41cf-9eeb-7c2825b0ea4d'::uuid, 'geom', 'SRID=4326;POINT(-3.518333 42.3525)', '0101000020E61000006514A3755B2D0CC074266463F42E4540', 'fields-wd1-2026-09-26b-s004-rollback:5f10ac9c-682b-41cf-9eeb-7c2825b0ea4d:geom', 'rollback of fields-wd1-2026-09-26b-s004: geom ''0101000020E61000006514A3755B2D0CC074266463F42E4540'' restored on Atapuerca Mountains', '[{"source": "https://en.wikipedia.org/wiki/Archaeological_site_of_Atapuerca", "url": "https://en.wikipedia.org/wiki/Archaeological_site_of_Atapuerca", "quote": "42°21′09″N 3°31′06″W", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=14905", "url": "https://www.megalithic.co.uk/article.php?sid=14905", "quote": "Latitude: 42.350000N Longitude: 3.5194W", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0129)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is the archaeological site of Atapuerca (the cave sites of the Trinchera and Cueva Mayor), which Wikipedia places at 42.3525, -3.518333 and the Megalithic Portal at 42.35, -3.5194; the stored point is the summit of the Sierra 1.6 km to the north, so it is replaced.", "value_page": null}]'::jsonb),
