    ('5f10ac9c-682b-41cf-9eeb-7c2825b0ea4d'::uuid, 'period_name', NULL, '< 4500 BC', 'fields-wd1-2026-09-26b-s004-rollback:5f10ac9c-682b-41cf-9eeb-7c2825b0ea4d:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''< 4500 BC'' restored on Atapuerca Mountains', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5f10ac9c-682b-41cf-9eeb-7c2825b0ea4d'::uuid, 'period_start', NULL, '-1400000', 'fields-wd1-2026-09-26b-s004-rollback:5f10ac9c-682b-41cf-9eeb-7c2825b0ea4d:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-1400000'' restored on Atapuerca Mountains', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0129)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia, Nature and the Megalithic Portal date the site''s oldest hominin fossils (Sima del Elefante) only as ages - 1.4 to 1.1 million years ago - and no source states a year, century or millennium for the start, so no quotable date exists and the field is emptied.", "value_page": null}]'::jsonb),
    ('5f10ac9c-682b-41cf-9eeb-7c2825b0ea4d'::uuid, 'site_type', 'Cave', 'Cave Structures', 'fields-wd1-2026-09-26b-s004-rollback:5f10ac9c-682b-41cf-9eeb-7c2825b0ea4d:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Cave Structures'' restored on Atapuerca Mountains', '[{"source": "https://www.megalithic.co.uk/article.php?sid=14905", "url": "https://www.megalithic.co.uk/article.php?sid=14905", "quote": "Type: Cave or Rock Shelter", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Archaeological_site_of_Atapuerca", "url": "https://en.wikipedia.org/wiki/Archaeological_site_of_Atapuerca", "quote": "found in its Gran Dolina cavern, provide the oldest known evidence of hominid settlement in Western Europe", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0129)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Megalithic Portal lists the Atapuerca Caves as a cave site and Wikipedia describes the finds from its natural karst caverns (Gran Dolina, Sima del Elefante, Sima de los Huesos); they are natural caves, not built cave structures, so Cave fits best.", "value_page": null}]'::jsonb),
    ('5f10ac9c-682b-41cf-9eeb-7c2825b0ea4d'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Archaeological_site_of_Atapuerca', 'https://en.wikipedia.org/wiki/Atapuerca_Mountains', 'fields-wd1-2026-09-26b-s004-rollback:5f10ac9c-682b-41cf-9eeb-7c2825b0ea4d:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/Atapuerca_Mountains'' restored on Atapuerca Mountains', '[{"source": "https://en.wikipedia.org/wiki/Archaeological_site_of_Atapuerca", "url": "https://en.wikipedia.org/wiki/Archaeological_site_of_Atapuerca", "quote": "The archaeological site of Atapuerca is located in the Province of Burgos in the north of Spain and is notable for its evidence of early human occupation.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=14905", "url": "https://www.megalithic.co.uk/article.php?sid=14905", "quote": "Site Name: Atapuerca Caves", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0129)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored article is about the Atapuerca mountain range; English Wikipedia has an article on the archaeological site itself, which the Megalithic Portal names as the Atapuerca Caves, so it replaces the stored URL.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Archaeological site of Atapuerca", "unreadable": false, "wikibase_item": "Q923894"}}]'::jsonb),
