    ('5f478ce8-5cb2-4a8f-bd80-95f64bae677a'::uuid, 'geom', 'SRID=4326;POINT(40.09293 38.25531)', '0101000020E610000010A6082C680A44404E78878FDC214340', 'fields-wd1-2026-09-26b-s004-rollback:5f478ce8-5cb2-4a8f-bd80-95f64bae677a:geom', 'rollback of fields-wd1-2026-09-26b-s004: geom ''0101000020E610000010A6082C680A44404E78878FDC214340'' restored on Eğil Kalesi', '[{"source": "https://www.wikidata.org/wiki/Q131902195", "url": "https://www.wikidata.org/wiki/Q131902195", "quote": "38°15''19.12\"N, 40°5''34.55\"E", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=46109", "url": "https://www.megalithic.co.uk/article.php?sid=46109", "quote": "Latitude: 38.257832N  Longitude: 40.095913E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0143)", "decision": "replace", "status": "MISSING", "reasoning": "Wikidata''s item for Eğil Castle (matching the OpenStreetMap outline of the castle on its rock above the Tigris) gives 38.25531, 40.09293, and the Megalithic Portal''s ''Fortress Egil'' lies 0.4 km from it; the stored point is about 1.45 km to the north-west in the Yenişehir quarter of the town, so it is replaced.", "value_page": null}]'::jsonb),
