    ('5f478ce8-5cb2-4a8f-bd80-95f64bae677a'::uuid, 'period_name', '1500 - 500 BC', '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s004-rollback:5f478ce8-5cb2-4a8f-bd80-95f64bae677a:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''4500 - 3000 BC'' restored on Eğil Kalesi', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-800) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5f478ce8-5cb2-4a8f-bd80-95f64bae677a'::uuid, 'period_start', '-800', '-3500', 'fields-wd1-2026-09-26b-s004-rollback:5f478ce8-5cb2-4a8f-bd80-95f64bae677a:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-3500'' restored on Eğil Kalesi', '[{"source": "https://mcid.mcah.columbia.edu/mapping-mesopotamian-monuments/egil-relief", "url": "https://mcid.mcah.columbia.edu/mapping-mesopotamian-monuments/egil-relief", "quote": "Late 8th century BC", "outcome": "found"}, {"source": "https://www.turkiyeroutes.com/historical/egil-castle", "url": "https://www.turkiyeroutes.com/historical/egil-castle", "quote": "The relief is believed to belong to the Assyrian King Salmanassar III (859-824 BC).", "outcome": "found"}, {"source": "https://kureansiklopedi.com/en/detay/egil-assyrian-castle-61ea9", "url": "https://kureansiklopedi.com/en/detay/egil-assyrian-castle-61ea9", "quote": "The origins of Eğil Castle date back to the period of Assyrian dominance in the region between 1260 and 606 BCE.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0143)", "decision": "replace", "status": "MISSING", "reasoning": "The earliest securely dated monument at the castle rock is the Neo-Assyrian relief, which Columbia''s Mapping Mesopotamian Monuments dates to the late 8th century BC (Turkiye Routes attributes it to Shalmaneser III, 859-824 BC), and Küre places the castle''s origins in the Assyrian period 1260-606 BCE; all lie in 1500 - 500 BC, while the stored -3500 rests only on the district''s general prehistory.", "value_page": null}]'::jsonb),
    ('5f478ce8-5cb2-4a8f-bd80-95f64bae677a'::uuid, 'source_url', 'https://diyarbakir.gov.tr/egil-asur-kalesi', 'https://gelecekpartisi-org-tr.translate.goog/diyarbakir/tanitim/asur-kalesi-egil?_x_tr_sl=tr&_x_tr_tl=en&_x_tr_hl=en&_x_tr_pto=sc', 'fields-wd1-2026-09-26b-s004-rollback:5f478ce8-5cb2-4a8f-bd80-95f64bae677a:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://gelecekpartisi-org-tr.translate.goog/diyarbakir/tanitim/asur-kalesi-egil?_x_tr_sl=tr&_x_tr_tl=en&_x_tr_hl=en&_x_tr_pto=sc'' restored on Eğil Kalesi', '[{"source": "https://diyarbakir.gov.tr/egil-asur-kalesi", "url": "https://diyarbakir.gov.tr/egil-asur-kalesi", "quote": "Eğil Kalesi’nde, Kültür ve Turizm Bakanlığı’nın izinleri doğrultusunda kazı çalışmaları devam etmektedir", "outcome": "found"}, {"source": "https://kureansiklopedi.com/en/detay/egil-assyrian-castle-61ea9", "url": "https://kureansiklopedi.com/en/detay/egil-assyrian-castle-61ea9", "quote": "The origins of Eğil Castle date back to the period of Assyrian dominance in the region between 1260 and 606 BCE.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0143)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored value is a Google Translate proxy of a political party''s promotional page; the Diyarbakır Governorship''s page ''Eğil Asur Kalesi'' is an official page about this castle (no Wikipedia article exists), and the Küre encyclopedia names the same castle.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('5f745388-3793-459b-b55f-90dbb5bfed78'::uuid, 'site_type', 'Gate', 'Infrastructure', 'fields-wd1-2026-09-26b-s004-rollback:5f745388-3793-459b-b55f-90dbb5bfed78:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Infrastructure'' restored on Lefke Gate', '[{"source": "https://kitabe.org/en/bursa/iznik-lefke-gate", "url": "https://kitabe.org/en/bursa/iznik-lefke-gate", "quote": "Lefke Gate, forming the eastern entrance of the Iznik city walls, is a monumental fortress gate bearing traces of the Roman and Byzantine periods.", "outcome": "found"}, {"source": "https://www.lonelyplanet.com/points-of-interest/lefke-gate/1029957", "url": "https://www.lonelyplanet.com/points-of-interest/lefke-gate/1029957", "quote": "Part of İznik''s Roman-Byzantine fortifications, the eastern Lefke Gate comprises three gateways dating from Byzantine times.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0145)", "decision": "replace", "status": "MISSING", "reasoning": "Kitabe and Lonely Planet both describe Lefke Gate as the eastern city gate of İznik''s walls; Gate is the specific canonical type, more precise than the generic Infrastructure.", "value_page": null}]'::jsonb),
    ('5f745388-3793-459b-b55f-90dbb5bfed78'::uuid, 'source_url', 'https://tr.wikipedia.org/wiki/Lefke_Kap%C4%B1s%C4%B1', 'https://www.lonelyplanet.com/turkey/iznik/attractions/lefke-gate/a/poi-sig/1029957/360888', 'fields-wd1-2026-09-26b-s004-rollback:5f745388-3793-459b-b55f-90dbb5bfed78:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://www.lonelyplanet.com/turkey/iznik/attractions/lefke-gate/a/poi-sig/1029957/360888'' restored on Lefke Gate', '[{"source": "https://tr.wikipedia.org/wiki/Lefke_Kap%C4%B1s%C4%B1", "url": "https://tr.wikipedia.org/wiki/Lefke_Kap%C4%B1s%C4%B1", "quote": "Lefke Kapısı veya tarihî adıyla Şam Kapısı", "outcome": "found"}, {"source": "https://kitabe.org/en/bursa/iznik-lefke-gate", "url": "https://kitabe.org/en/bursa/iznik-lefke-gate", "quote": "Lefke Gate, forming the eastern entrance of the Iznik city walls, is a monumental fortress gate bearing traces of the Roman and Byzantine periods.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0145)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Lonely Planet URL is an old address that redirects; there is no English Wikipedia article on the gate, but the Turkish Wikipedia article Lefke Kapısı is about this very gate of İznik, so it becomes the source page.", "value_page": {"lang": "tr", "problem": null, "resolved_title": "Lefke Kapısı", "unreadable": false, "wikibase_item": "Q6063111"}}]'::jsonb),
    ('5f77f387-c246-4943-821e-259e4d4f50ab'::uuid, 'site_type', 'Barrow', 'Necropolis/tombs complex', 'fields-wd1-2026-09-26b-s004-rollback:5f77f387-c246-4943-821e-259e4d4f50ab:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Necropolis/tombs complex'' restored on Grønsalen', '[{"source": "https://en.wikipedia.org/wiki/Gr%C3%B8nsalen", "url": "https://en.wikipedia.org/wiki/Gr%C3%B8nsalen", "quote": "The barrow, rising over a metre above the surrounding area, is encircled by 134 large stones.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=18245", "url": "https://www.megalithic.co.uk/article.php?sid=18245", "quote": "Type: Long Barrow", "outcome": "found"}, {"source": "https://www.kulturarv.dk/fundogfortidsminder/Lokalitet/90001/", "url": "https://www.kulturarv.dk/fundogfortidsminder/Lokalitet/90001/", "quote": "Grønjægers Høj eller Grønsalen syd for Fanefjord Kirke er en af landets bedst bevarede langdysser.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0021)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia, the Megalithic Portal and the Danish national register all describe Grønsalen as a single long barrow (langdysse) with three chambers, not a necropolis or tomb complex, so Barrow is the fitting type.", "value_page": null}]'::jsonb),
    ('5fb67acb-15e7-4e73-ab27-3d729a0b74b9'::uuid, 'site_type', 'Gate', 'Gate/archway/bridge', 'fields-wd1-2026-09-26b-s004-rollback:5fb67acb-15e7-4e73-ab27-3d729a0b74b9:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Gate/archway/bridge'' restored on Bishopsgate', '[{"source": "https://en.wikipedia.org/wiki/Bishopsgate", "url": "https://en.wikipedia.org/wiki/Bishopsgate", "quote": "Bishopsgate was one of the eastern gates in London''s former defensive wall", "outcome": "found"}, {"source": "https://www.londonremembers.com/memorials/bishopsgate", "url": "https://www.londonremembers.com/memorials/bishopsgate", "quote": "As one of the original Roman city gates, Bishopsgate followed the path of an old Roman road", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0027)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources describe the site as one of the Roman city gates of London Wall (the Wikidata item Q779444 is the later ward named after it); Gate is the most specific canonical type, narrower than Gate/archway/bridge.", "value_page": null}]'::jsonb),
    ('5ff6c53b-4318-43e4-83df-706186ddc942'::uuid, 'period_name', NULL, '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s004-rollback:5ff6c53b-4318-43e4-83df-706186ddc942:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''3000 - 1500 BC'' restored on Atsipades', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('5ff6c53b-4318-43e4-83df-706186ddc942'::uuid, 'period_start', NULL, '-3000', 'fields-wd1-2026-09-26b-s004-rollback:5ff6c53b-4318-43e4-83df-706186ddc942:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-3000'' restored on Atsipades', '[{"source": "WD1 decision (counted, round 1, wd1-r1-b0009)", "decision": "clear", "status": "MISSING", "reasoning": "The readable sources do not give one dated start for the Atsipades Korakias peak sanctuary: English Wikipedia dates its use to around 2300 to 1700 B.C.E. (Early Minoan III to Middle Minoan II) but also notes Final Neolithic pottery in rock cracks, the DEFC database lists only Final Neolithic periods, a local guide says 3000 to 1200 BC and a Rethymno culture page speaks of Late Minoan remains; no two independent reliable sources agree on a year, and the original excavation paper (Classics Ireland) cannot be read, so the stored -3000 is emptied.", "value_page": null}]'::jsonb),
    ('5fffbfc9-f83c-4cd3-9b8d-d2570ce63dbd'::uuid, 'source_url', 'https://mk.wikipedia.org/wiki/%D0%90%D1%81%D1%82%D0%B8%D0%B1%D0%BE', 'https://en.wikipedia.org/wiki/History', 'fields-wd1-2026-09-26b-s004-rollback:5fffbfc9-f83c-4cd3-9b8d-d2570ce63dbd:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/History'' restored on Estipeon', '[{"source": "https://mk.wikipedia.org/wiki/%D0%90%D1%81%D1%82%D0%B8%D0%B1%D0%BE", "url": "https://mk.wikipedia.org/wiki/%D0%90%D1%81%D1%82%D0%B8%D0%B1%D0%BE", "quote": "Населбата егзистирала и во доцноантичкиот и рановизантискиот период под името Стипион", "outcome": "found"}, {"source": "http://www.exploringmacedonia.com/stip.nspx", "url": "http://www.exploringmacedonia.com/stip.nspx", "quote": "However, a new settlement - Estipeon - was soon founded on the same site which thrived though the late Roman and the Early Byzantine period.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0100)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the generic article ''History''; the English ''Astibo'' and ''Estipeon'' are only redirects to the modern city Štip, while the Macedonian Wikipedia article ''Астибо'' (the Wikidata item''s own article) is about the ancient town itself and says it lived on in late antiquity as Stipion, the Estipeon that the Macedonian tourism portal places on the same site.", "value_page": {"lang": "mk", "problem": null, "resolved_title": "Астибо", "unreadable": false, "wikibase_item": "Q4810863"}}]'::jsonb),
    ('600e2f90-b845-4def-a440-10a45e1da307'::uuid, 'period_name', NULL, '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s004-rollback:600e2f90-b845-4def-a440-10a45e1da307:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''3000 - 1500 BC'' restored on Kleczanów Forest', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('600e2f90-b845-4def-a440-10a45e1da307'::uuid, 'period_start', NULL, '-3000', 'fields-wd1-2026-09-26b-s004-rollback:600e2f90-b845-4def-a440-10a45e1da307:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-3000'' restored on Kleczanów Forest', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0116)", "decision": "clear", "status": "MISSING", "reasoning": "The heritage register dates the cemetery''s use to the 8th-10th century AD but says the oldest of its mounds was probably raised by the Corded Ware culture (ca. 2,800-2,300 BC). English Wikipedia also puts the first burials in the late Stone Age, though without a date. Only one source dates the prehistoric start, and it hedges it as ''probably'', while an 8th-century start would contradict both sources, so no start is attested by two sources.", "value_page": null}]'::jsonb),
    ('600e2f90-b845-4def-a440-10a45e1da307'::uuid, 'site_type', 'Barrow', 'Necropolis/tombs complex', 'fields-wd1-2026-09-26b-s004-rollback:600e2f90-b845-4def-a440-10a45e1da307:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Necropolis/tombs complex'' restored on Kleczanów Forest', '[{"source": "https://zabytek.pl/en/obiekty/kleczanow-cmentarzysko-kurhanowe", "url": "https://zabytek.pl/en/obiekty/kleczanow-cmentarzysko-kurhanowe", "quote": "The early medieval barrow cemetery in Kleczanów has 37 well-preserved mounds of different size and morphology.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Kleczan%C3%B3w", "url": "https://en.wikipedia.org/wiki/Kleczan%C3%B3w", "quote": "iis known for featuring an ancient site of 37 Slavic kurgans (burial mounds) 4–10 metres high.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0116)", "decision": "replace", "status": "CONFLICT", "reasoning": "The national heritage register and Wikipedia both describe the site as a cemetery of 37 barrows (kurgans, burial mounds). ''Barrow'' is the most specific canonical type for that and is more precise than the stored ''Necropolis/tombs complex'', which neither source uses.", "value_page": null}]'::jsonb),
    ('600e2f90-b845-4def-a440-10a45e1da307'::uuid, 'source_url', 'https://zabytek.pl/en/obiekty/kleczanow-cmentarzysko-kurhanowe', 'https://en.wikipedia.org/wiki/Kleczan%C3%B3w_Forest', 'fields-wd1-2026-09-26b-s004-rollback:600e2f90-b845-4def-a440-10a45e1da307:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/Kleczan%C3%B3w_Forest'' restored on Kleczanów Forest', '[{"source": "https://zabytek.pl/en/obiekty/kleczanow-cmentarzysko-kurhanowe", "url": "https://zabytek.pl/en/obiekty/kleczanow-cmentarzysko-kurhanowe", "quote": "The cemetery is located in the wood west of the village of Kleczanów, on the west side of the Sandomierz-Opatów road.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Kleczan%C3%B3w", "url": "https://en.wikipedia.org/wiki/Kleczan%C3%B3w", "quote": "Although the whole surrounding landscape was transformed into farmland, the Kleczanów Woods survived untouched.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0116)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL redirects into the History section of the village article. There is no Wikipedia article on the site itself, so the national heritage register entry (NID, zabytek.pl) for the Kleczanów barrow cemetery replaces it; English Wikipedia describes the same wood and its kurgans.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('612ff287-3919-4ae9-bb6b-50ea7548b64b'::uuid, 'period_name', '1000 - 1500 AD', '1 - 500 AD', 'fields-wd1-2026-09-26b-s004-rollback:612ff287-3919-4ae9-bb6b-50ea7548b64b:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''1 - 500 AD'' restored on Huacramarca', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(1101) = ''1000 - 1500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('612ff287-3919-4ae9-bb6b-50ea7548b64b'::uuid, 'period_start', '1101', '1', 'fields-wd1-2026-09-26b-s004-rollback:612ff287-3919-4ae9-bb6b-50ea7548b64b:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''1'' restored on Huacramarca', '[{"source": "https://pdfs.semanticscholar.org/b40e/cfa7a6aab8d8ddaa5f4bb02f989b7ff5e43d.pdf", "url": "https://pdfs.semanticscholar.org/b40e/cfa7a6aab8d8ddaa5f4bb02f989b7ff5e43d.pdf", "quote": "ocupación principal de Huacramarca ocurrió entre los siglos XII y XIII de nuestra era, dentro de la primera mitad del Período Intermedio Tardío", "outcome": "found"}, {"source": "https://es.wikipedia.org/wiki/Huacramarca", "url": "https://es.wikipedia.org/wiki/Huacramarca", "quote": "su ocupación inició durante el período Intermedio Tardío (1200 d. C.)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0108)", "decision": "replace", "status": "MISSING", "reasoning": "The excavation report''s radiocarbon series puts the main occupation of Huacramarca in the 12th-13th centuries AD (earlier 6th-9th century traces are only possible), and Spanish Wikipedia, after Herrera''s survey, has its occupation begin in the Late Intermediate Period (1200 AD); the start lies in the 1000-1500 AD bucket, not the stored 1-500 AD.", "value_page": null}]'::jsonb),
    ('6148883a-659c-40c4-bcf4-ef086f860f40'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s004-rollback:6148883a-659c-40c4-bcf4-ef086f860f40:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Fortress/citadel'' restored on Waddon Hill', '[{"source": "https://heritage.dorsetcouncil.gov.uk/Monument/MDO2531", "url": "https://heritage.dorsetcouncil.gov.uk/Monument/MDO2531", "quote": "Earthworks associated with the Roman fort on Waddon Hill are visible on aerial photographs of the 1940s and 1970s.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Waddon_Hill", "url": "https://en.wikipedia.org/wiki/Waddon_Hill", "quote": "Waddon Hill is a hill and the site of a short-lived Roman fort near Beaminster", "outcome": "found"}, {"source": "https://beaminstermuseum.co.uk/the-waddon-hill-roman-fort-project/", "url": "https://beaminstermuseum.co.uk/the-waddon-hill-roman-fort-project/", "quote": "Waddon Hill Roman Fort sits just outside Broadwindsor, above Stoke Abbott.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0047)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Dorset HER (type FORT, Roman), Wikipedia and Beaminster Museum all describe the site as a short-lived Roman fort of the conquest period; Fort is the most specific canonical type, not a fortress or citadel.", "value_page": null}]'::jsonb),
    ('616719a2-c7ee-4162-b6f6-da52b85dbc4a'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s004-rollback:616719a2-c7ee-4162-b6f6-da52b85dbc4a:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Fortress/citadel'' restored on Matilo', '[{"source": "https://www.livius.org/articles/place/matilo-leiden-roomburg/", "url": "https://www.livius.org/articles/place/matilo-leiden-roomburg/", "quote": "Matilo: Roman fort, part of the limes in Germania Inferior", "outcome": "found"}, {"source": "https://cultuurwijzer.nl/leiden-matilo/", "url": "https://cultuurwijzer.nl/leiden-matilo/", "quote": "In de Leidse polder Roomburg lag een Romeins fort (castellum)", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Matilo", "url": "https://en.wikipedia.org/wiki/Matilo", "quote": "Matilo or Matilone was once a Roman fort (castellum) in modern-day Leiden.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0099)", "decision": "replace", "status": "CONFLICT", "reasoning": "Livius, Cultuurwijzer and Wikipedia all describe Matilo as a Roman auxiliary fort (castellum) on the Lower German Limes. ''Fort'' is the specific type; ''Fortress/citadel'' overstates a small auxiliary castellum.", "value_page": null}]'::jsonb),
    ('617627d7-010d-4aa2-a9da-0d3160855f8a'::uuid, 'period_name', '1500 - 500 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s004-rollback:617627d7-010d-4aa2-a9da-0d3160855f8a:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''3000 - 1500 BC'' restored on Castell Dinas', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-800) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('617627d7-010d-4aa2-a9da-0d3160855f8a'::uuid, 'period_start', '-800', '-3000', 'fields-wd1-2026-09-26b-s004-rollback:617627d7-010d-4aa2-a9da-0d3160855f8a:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-3000'' restored on Castell Dinas', '[{"source": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=3820", "url": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=3820", "quote": "The monument comprises the remains of a hillfort, which probably dates to the Iron Age period (c. 800 BC - AD 74, the Roman conquest of Wales)", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Castell_Dinas", "url": "https://en.wikipedia.org/wiki/Castell_Dinas", "quote": "This site was originally an Iron Age, 600 BC to 50 AD, hillfort.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0153)", "decision": "replace", "status": "MISSING", "reasoning": "Cadw''s scheduling record BR015 dates the hillfort probably to the Iron Age, c. 800 BC - AD 74, and Wikipedia gives an Iron Age hillfort of 600 BC to 50 AD; neither mentions earlier use, so the start is c. 800 BC (1500 - 500 BC bucket), not the stored 3000 BC.", "value_page": null}]'::jsonb),
    ('61ae1b37-1703-4754-880a-f7277504a829'::uuid, 'period_name', '500 BC - 1 AD', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s004-rollback:61ae1b37-1703-4754-880a-f7277504a829:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''3000 - 1500 BC'' restored on Apamea', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-300) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('61ae1b37-1703-4754-880a-f7277504a829'::uuid, 'period_start', '-300', '-3000', 'fields-wd1-2026-09-26b-s004-rollback:61ae1b37-1703-4754-880a-f7277504a829:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-3000'' restored on Apamea', '[{"source": "https://en.wikipedia.org/wiki/Apamea,_Syria", "url": "https://en.wikipedia.org/wiki/Apamea,_Syria", "quote": "it was established as a fortified city around 300 BC by Seleucus I Nicator", "outcome": "found"}, {"source": "https://sana.sy/en/tour-syria/2322517/", "url": "https://sana.sy/en/tour-syria/2322517/", "quote": "Apamea was founded by Seleucus I Nicator between 300 and 299 BC and named after his Persian wife Apama.", "outcome": "found"}, {"source": "https://arscan.parisnanterre.fr/apamea-the-citadel-qalaat-al-mudiq/", "url": "https://arscan.parisnanterre.fr/apamea-the-citadel-qalaat-al-mudiq/", "quote": "The initial results of the mission led to the discovery of Hellenistic walls dating back to the early 3rd century BC, shedding new light on the citadel of the city of Apamea.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0138)", "decision": "replace", "status": "CONFLICT", "reasoning": "Apamea was founded as a city by Seleucus I around 300 BC (Wikipedia, SANA), on the spot of the Macedonian settlement Pella (c. 320 BC), and the earliest walls found on its citadel date to the early 3rd century BC (ArScAn/CNRS mission). The Bronze Age tell under the citadel is an undated earlier settlement, so nothing supports the stored 3000 BC; the start is -300, in 500 BC - 1 AD.", "value_page": null}]'::jsonb),
    ('61d2ef8c-e4a4-4dca-b7e7-36d58f391b60'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s004-rollback:61d2ef8c-e4a4-4dca-b7e7-36d58f391b60:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''1500 - 500 BC'' restored on Kelsey Head', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('61d2ef8c-e4a4-4dca-b7e7-36d58f391b60'::uuid, 'period_start', NULL, '-1000', 'fields-wd1-2026-09-26b-s004-rollback:61d2ef8c-e4a4-4dca-b7e7-36d58f391b60:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-1000'' restored on Kelsey Head', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0038)", "decision": "clear", "status": "MISSING", "reasoning": "Only the National Trust record gives a date (Iron Age, 800 BC to 42 AD, a generic period range); Wikipedia and the Megalithic Portal say only ''Iron Age'' without a year, and the South West Coast Path page dates cliff castles generally to AD 100-200. No two independent sources date the start of this cliff castle, so the field is emptied.", "value_page": null}]'::jsonb),
    ('61d2ef8c-e4a4-4dca-b7e7-36d58f391b60'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s004-rollback:61d2ef8c-e4a4-4dca-b7e7-36d58f391b60:site_type', 'rollback of fields-wd1-2026-09-26b-s004: site_type ''Fortress/citadel'' restored on Kelsey Head', '[{"source": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA103632", "url": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA103632", "quote": "Kelsey Head Camp is a Iron Age promontory Hill Fort situated on the coast line.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=8427", "url": "https://www.megalithic.co.uk/article.php?sid=8427", "quote": "Settlement and cliff fort high on exposed cliffs between Holywell Bay and Newquay", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0038)", "decision": "replace", "status": "CONFLICT", "reasoning": "The National Trust heritage record and the Megalithic Portal both describe the site as an Iron Age promontory fort (cliff castle, cliff fort); nothing calls it a fortress or citadel, so the specific type is Fort.", "value_page": null}]'::jsonb),
    ('61d2ef8c-e4a4-4dca-b7e7-36d58f391b60'::uuid, 'source_url', 'https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA103632', 'https://en.wikipedia.org/wiki/Kelsey_Head', 'fields-wd1-2026-09-26b-s004-rollback:61d2ef8c-e4a4-4dca-b7e7-36d58f391b60:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/Kelsey_Head'' restored on Kelsey Head', '[{"source": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA103632", "url": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA103632", "quote": "Iron Age Promontory Fort of Kelsey Head Camp, Cubert and The Kelseys", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=8427", "url": "https://www.megalithic.co.uk/article.php?sid=8427", "quote": "Site Name: Kelsey Head Fort", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0038)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Wikipedia article is about the Kelsey Head headland and its biological SSSI, with the cliff castle in a two-sentence history section; the National Trust heritage record MNA103632 is the entry for the Iron Age promontory fort itself, which the Megalithic Portal also names.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('627ffcd0-ad25-4ff3-ae0d-5bc37d2053ef'::uuid, 'period_name', '3000 - 1500 BC', '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s004-rollback:627ffcd0-ad25-4ff3-ae0d-5bc37d2053ef:period_name', 'rollback of fields-wd1-2026-09-26b-s004: period_name ''4500 - 3000 BC'' restored on Chanhudaro', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-2600) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('627ffcd0-ad25-4ff3-ae0d-5bc37d2053ef'::uuid, 'period_start', '-2600', '-4500', 'fields-wd1-2026-09-26b-s004-rollback:627ffcd0-ad25-4ff3-ae0d-5bc37d2053ef:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-4500'' restored on Chanhudaro', '[{"source": "https://shs.hal.science/halshs-05431314", "url": "https://shs.hal.science/halshs-05431314", "quote": "a planned city built of mud brick dated from the first centuries of the Indus Civilization (2600/2500-2300 BCE)", "outcome": "found"}, {"source": "https://hal.science/hal-05434452v1", "url": "https://hal.science/hal-05434452v1", "quote": "the complete occupation sequence of Chanhu-daro covering the entire urban period (2600/2500-1900 BCE)", "outcome": "found"}, {"source": "https://www.livehistoryindia.com/story/monuments/chanhudaro", "url": "https://www.livehistoryindia.com/story/monuments/chanhudaro", "quote": "The lowest levels belong to the Harappan culture (3rd millennium BCE), the earliest of the three", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0103)", "decision": "replace", "status": "MISSING", "reasoning": "The French-Pakistani mission now excavating Chanhu-daro (MAFBI, Didier) dates the earliest excavated city to the first Indus period, 2600/2500 BCE, and has not reached virgin soil, and Live History India likewise puts the lowest, Harappan levels in the 3rd millennium BCE; the 4000 BCE start in Wikipedia is not attested by the excavations, so the start c. 2600 BC falls in the bucket 3000-1500 BC, not the stored 4500-3000 BC.", "value_page": null}]'::jsonb),
