    ('6287ace1-7bcd-4b92-91c9-5cc2be238981'::uuid, 'period_start', NULL, '-1500', 'fields-wd1-2026-09-26b-s004-rollback:6287ace1-7bcd-4b92-91c9-5cc2be238981:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-1500'' restored on Więckowy', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0117)", "decision": "clear", "status": "MISSING", "reasoning": "The sources only say the flat cemetery is from the Iron Age (''z epoki żelaza'', ''a cemetery from the Iron Age''); none gives a year, century or millennium, so no attested start year can be quoted and the stored -1500 is unsupported.", "value_page": null}]'::jsonb),
    ('6287ace1-7bcd-4b92-91c9-5cc2be238981'::uuid, 'source_url', 'https://zabytek.pl/pl/obiekty/g-290750', 'https://en.wikipedia.org/wiki/Wi%C4%99ckowy', 'fields-wd1-2026-09-26b-s004-rollback:6287ace1-7bcd-4b92-91c9-5cc2be238981:source_url', 'rollback of fields-wd1-2026-09-26b-s004: source_url ''https://en.wikipedia.org/wiki/Wi%C4%99ckowy'' restored on Więckowy', '[{"source": "https://zabytek.pl/pl/obiekty/g-290750", "url": "https://zabytek.pl/pl/obiekty/g-290750", "quote": "cmentarzysko kurhan Więckowy", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Wi%C4%99ckowy", "url": "https://en.wikipedia.org/wiki/Wi%C4%99ckowy", "quote": "Human settlement dates back to prehistoric times and there is a cemetery from the Iron Age near the village, now an archaeological site.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0117)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is about the village of Więckowy; the NID heritage register entry g-290750 is the page about the registered cemetery at Więckowy itself, which Wikipedia also mentions as an Iron Age cemetery near the village.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
