    ('62a60a9e-24f1-40ac-a678-a7c0a6d91ce1'::uuid, 'period_start', '201', '-3000', 'fields-wd1-2026-09-26b-s004-rollback:62a60a9e-24f1-40ac-a678-a7c0a6d91ce1:period_start', 'rollback of fields-wd1-2026-09-26b-s004: period_start ''-3000'' restored on Din Lligwy Hut Circle', '[{"source": "https://cadw.gov.wales/visit/places-to-visit/din-llugwy-romano-british-village", "url": "https://cadw.gov.wales/visit/places-to-visit/din-llugwy-romano-british-village", "quote": "Discoveries of coins, pottery and glass date the settlement to the late Roman period in the 3rd and 4th centuries, though traces of structures outside the enclosure suggest the site may have been in use since the Iron Age.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Din_Lligwy", "url": "https://en.wikipedia.org/wiki/Din_Lligwy", "quote": "produced hundreds of Roman-period pot sherds of the 3rd and 4th centuries CE", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0153)", "decision": "replace", "status": "MISSING", "reasoning": "Cadw and Wikipedia both date the excavated occupation of the enclosed settlement to the 3rd and 4th centuries AD; an Iron Age origin is only suggested (Cadw: ''may have been in use''), so the attested start is the 3rd century AD (201), in the 1 - 500 AD bucket, not the stored 3000 BC.", "value_page": null}]'::jsonb),
